insert into "monthly_asset_class_outlook" ("path", "hs_name", "week_slug", "main_title", "page_subtitle", "sub_title", "page_date", "week_start_date", "week_end_date", "cover_image", "description", "ai_summary", "body", "is_published") values ('2026-05-01-equity', 'มุมมองตราสารทุนเดือนพฤษภาคม 2569: เลือกสหรัฐฯ ญี่ปุ่น และไทย ลดน้ำหนักยุโรป คง Neutral จีน', '2026-05-01', 'มุมมองตราสารทุนเดือนพฤษภาคม 2569: เลือกสหรัฐฯ ญี่ปุ่น และไทย ลดน้ำหนักยุโรป คง Neutral จีน', 'มุมมองการลงทุนรายเดือน — ตราสารทุน พฤษภาคม 2569', 'ตราสารทุน', '2026-05-01', '2026-05-01', '2026-05-31', '{"url": "https://43844850.fs1.hubspotusercontent-na2.net/hubfs/43844850/monthly-reports/20260505_Yuanta_Monthly_Asset_Allocation_May_2026/page_035.png", "altText": "", "type": "image"}'::jsonb, 'ห้าตลาด ห้าเรื่องราว — เดือนพฤษภาคมนี้ Yuanta CIO ชี้ทิศทางตราสารทุนทั่วโลกท่ามกลางสัญญาณหยุดยิง กำไรที่แข็งแกร่งกว่าคาด และแรงกดดันพลังงานที่ยังไม่จางหาย', '<p><span>ตลาดหุ้นสหรัฐฯ และญี่ปุ่นได้รับคำแนะนำ Slightly Overweight จากกำไรที่ยังเติบโตในกลุ่มเทคโนโลยีและเซมิคอนดักเตอร์ ขณะที่ยุโรปถูกลดน้ำหนักเป็น Slightly Underweight จากความเสี่ยง ECB ขึ้นดอกเบี้ยและ Valuation ที่แพงกว่าสหรัฐฯ ในเชิงเปรียบเทียบ</span></p><p><span>จีนคง Neutral เนื่องจากกำไรถูกปรับลดต่อเนื่อง ส่วนไทยยืน Slightly Overweight โดยเน้นทยอยสะสมกลุ่ม Domestic Recovery และ Policy Beneficiary</span></p>', '<h3><span>ภาพรวมตราสารทุนโลก เดือนพฤษภาคม 2569</span></h3>
<p><span>ในเดือนพฤษภาคม 2569 ตลาดตราสารทุนทั่วโลกเผชิญกับบรรยากาศที่แตกต่างกันอย่างชัดเจนในแต่ละภูมิภาค ปัจจัยร่วมที่กดดันตลาดโดยรวมคือราคาพลังงานที่ยังทรงตัวสูงจากความตึงเครียดในตะวันออกกลาง อย่างไรก็ดี ผลประกอบการบริษัทจดทะเบียนในสหรัฐฯ ที่ออกมาดีกว่าคาด ประกอบกับสัญญาณการหยุดยิงที่เริ่มปรากฏ ช่วยพยุง Sentiment โดยรวมให้ไม่ทรุดลงมาก Yuanta CIO ยังคงใช้กลยุทธ์ Sector Selection และ Stock Selection อย่างระมัดระวัง โดยเน้นกลุ่มที่มีกำไรเติบโตชัดเจนและ Valuation ไม่ตึงเกินไป</span></p>
<p>&nbsp;</p>

<div style=''border:1px solid #e6e9ee;border-radius:10px;margin-bottom:16px;overflow:hidden;''>
  <div style=''display:flex;justify-content:space-between;align-items:center;gap:10px;padding:12px 16px;background:#f7f8fa;border-bottom:1px solid #e6e9ee;''>
    <span style=''font-size:16px;font-weight:700;color:#16202e;''>หุ้นสหรัฐฯ (US Equity)</span>
    <span style=''display:inline-block;font-size:12px;font-weight:700;border-radius:6px;padding:2px 9px;background:#e7f4ec;border:1px solid #b6dcc4;color:#1f7a4d;''>Slightly Overweight</span>
  </div>
  <div style=''padding:14px 16px;''>
    <p><span>ภาพรวม: ตลาดหุ้นสหรัฐฯ พลิกฟื้นกลับมาในเดือนเมษายนที่ผ่านมา โดยมีแรงหนุนจากสัญญาณหยุดยิงที่บ่งชี้ว่าผ่านจุดที่เลวร้ายที่สุดไปแล้ว และผลประกอบการโดยรวมที่ดีกว่าคาด ส่งผลให้ S&P 500 ปรับตัวขึ้นเหนือระดับ 7,000 จุดได้ ธนาคารกลางสหรัฐฯ ยังคงเดินหน้าแนวทาง Higher for Longer โดยคงดอกเบี้ยไว้ในระดับสูงท่ามกลางตลาดแรงงานที่ยังเปราะบาง</span></p>
    <p><span style=''font-weight:700;''>ปัจจัยสนับสนุน</span></p>
    <ul>
      <li><span>ผลประกอบการบริษัทจดทะเบียน 26% แรกที่รายงานออกมามี Earning Surprise ราว 10.65% สูงกว่าค่าเฉลี่ยในอดีต พร้อมการปรับประมาณการกำไร Bottom-Up ขึ้นในทุกไตรมาสจนถึงสิ้นปี 2026 โดย EPS คาดอยู่ที่ 80.18 ใน 1Q26 ไปจนถึง 88.91 ใน 4Q26</span></li>
      <li><span>Valuation กลับมาซื้อขายในระดับ Forward PER บริเวณ +0.5 – 0.75 SD จากค่าเฉลี่ย 5 ปี (Mean: 20.04x, +1SD: 21.90x) ซึ่งยังไม่ตึงเกินไปเมื่อเทียบกับ FWD EPS Growth ปี 2026 ที่ 22.49%</span></li>
      <li><span>เป้าหมายดัชนี S&P 500 บริเวณ 7,771 จุด ยังเป็นระดับที่ Yuanta CIO ประเมินว่าเหมาะสม</span></li>
    </ul>
    <p><span style=''font-weight:700;''>ปัจจัยเสี่ยง</span></p>
    <ul>
      <li><span>หากกำไรกลุ่มเทคโนโลยีเริ่มอ่อนตัวลง ดัชนีอาจยืนเหนือระดับ +1 SD ได้ยาก ซึ่งเป็นความกังวลหลักในแง่ความต่อเนื่องของ Earnings มากกว่า Valuation</span></li>
      <li><span>หากเฟดพลิกกลับมาส่งสัญญาณขึ้นดอกเบี้ย ดัชนีมีโอกาสทดสอบกรอบล่างที่ระดับ 6,460 จุด แม้กรณีฐานของ Yuanta CIO ไม่ได้รวมสมมติฐานนี้ไว้</span></li>
    </ul>
    <p><span style=''font-weight:700;''>แนวโน้ม/กลยุทธ์:</span> <span>คง Slightly Overweight สำหรับ Satellite Portfolio ในระยะ 12 เดือนข้างหน้า เน้นกลยุทธ์ Sector Selection กลุ่มเซมิคอนดักเตอร์ผ่าน ETF SMH, กองทุนรวม SCBSEMI(A) และ DR อย่าง NVDA19 โดยราคาหุ้น NVDA ยังซื้อขายบน Forward PER 22 เท่า ต่ำกว่าค่าเฉลี่ย 5 ปี</span></p>
    <p><img src=''https://43844850.fs1.hubspotusercontent-na2.net/hubfs/43844850/monthly-reports/20260505_Yuanta_Monthly_Asset_Allocation_May_2026/page_035.png'' width=''1282'' height=''890'' loading=''lazy'' alt=''S&P 500 Bottom-Up EPS Estimates 2026'' style=''height: auto; max-width: 100%; width: 1282px; margin-left: auto; margin-right: auto; display: block;''></p>
  </div>
</div>

<p>&nbsp;</p>

<div style=''border:1px solid #e6e9ee;border-radius:10px;margin-bottom:16px;overflow:hidden;''>
  <div style=''display:flex;justify-content:space-between;align-items:center;gap:10px;padding:12px 16px;background:#f7f8fa;border-bottom:1px solid #e6e9ee;''>
    <span style=''font-size:16px;font-weight:700;color:#16202e;''>หุ้นยุโรป (EU Equity)</span>
    <span style=''display:inline-block;font-size:12px;font-weight:700;border-radius:6px;padding:2px 9px;background:#fbecec;border:1px solid #f0c6c6;color:#b3372f;''>Slightly Underweight</span>
  </div>
  <div style=''padding:14px 16px;''>
    <p><span>ภาพรวม: ตลาดหุ้นยุโรป Underperform อย่างต่อเนื่อง เนื่องจากราคาพลังงานที่สูงจากสงครามตะวันออกกลางกดดันต้นทุนการผลิต ขณะที่ Valuation เมื่อเทียบกับสหรัฐฯ ยังค่อนข้างแพง โดยปัจจุบันอัตราส่วน S&P 500 / Stoxx 600 Forward PER อยู่ต่ำกว่า 1.3 เท่า ซึ่งสะท้อนว่ายุโรปซื้อขายถูกกว่าสหรัฐฯ แต่ด้วยผลประกอบการที่อ่อนแอกว่า จึงยากที่จะ Re-rate ได้ในระยะสั้น</span></p>
    <p><span style=''font-weight:700;''>ปัจจัยสนับสนุน</span></p>
    <ul>
      <li><span>แผน Fiscal Stimulus ของเยอรมนี ทั้ง Infrastructure Fund ขนาด EUR 500 พันล้าน และแผนกู้ยืมเพิ่มเติม เป็น Upside สำคัญสำหรับกลุ่ม Electrification, Grid Upgrade, Data Center, อุตสาหกรรม และก่อสร้าง</span></li>
      <li><span>กลุ่มธนาคารยุโรปยังรายงานกำไรดีกว่าคาดจาก NIM ที่ทรงตัว ขณะที่กลุ่มกลาโหมได้แรงหนุนจากการเร่งงบประมาณด้านความมั่นคง และ Siemens Energy ปรับ Outlook ปี 2026 ขึ้นจากคำสั่งซื้ออุปกรณ์ไฟฟ้าและ Grid ที่เชื่อมโยงกับ Data Center</span></li>
      <li><span>SAP เติม Growth Story ให้ยุโรปจากรายได้ Cloud ที่เติบโตดีกว่าคาด ส่วน ASML และ BESI สะท้อนว่า AI Capex ยังไหลมาถึงต้นน้ำของยุโรปจาก AI Chip Demand และ Hybrid Bonding ที่เร่งตัว</span></li>
    </ul>
    <p><span style=''font-weight:700;''>ปัจจัยเสี่ยง</span></p>
    <ul>
      <li><span>เงินเฟ้อ Eurozone เดือนเมษายน 2026 เร่งขึ้นเป็น 3% สวนทางกับ GDP 1Q26 ที่โตเพียง 0.1% ทำให้ ECB คงดอกเบี้ย Deposit Facility ที่ 2% พร้อมส่งสัญญาณ Upside Risks ต่อเงินเฟ้อทวีความรุนแรงขึ้น และตลาดเริ่ม Price-in การขึ้นดอกเบี้ยครั้งแรกในเดือนมิถุนายน 2026</span></li>
      <li><span>โครงสร้างตลาดยุโรปยังพึ่งพากลุ่ม Value มากกว่า Growth ทำให้ Upside จำกัด ขณะที่ LVMH, Hermes และ Kering ส่งสัญญาณว่าการฟื้นตัวของ Luxury ยังไม่ราบรื่น กดดันทั้ง Valuation และ Earnings Support พร้อมกัน</span></li>
    </ul>
    <p><span style=''font-weight:700;''>แนวโน้ม/กลยุทธ์:</span> <span>คง Slightly Underweight สำหรับการลงทุนในระยะ 12 เดือนข้างหน้า เนื่องจาก Valuation ยังแพงในเชิงเปรียบเทียบกับสหรัฐฯ ประกอบกับความเสี่ยงที่ ECB อาจกลับมาขึ้นดอกเบี้ยเพื่อสกัดเงินเฟ้อพลังงาน ทำให้ Upside ในระยะนี้ยังจำกัด</span></p>
    <p><img src=''https://43844850.fs1.hubspotusercontent-na2.net/hubfs/43844850/monthly-reports/20260505_Yuanta_Monthly_Asset_Allocation_May_2026/page_036.png'' width=''1282'' height=''890'' loading=''lazy'' alt=''Europe vs US Valuation and MSCI Growth Value'' style=''height: auto; max-width: 100%; width: 1282px; margin-left: auto; margin-right: auto; display: block;''></p>
  </div>
</div>

<p>&nbsp;</p>

<div style=''border:1px solid #e6e9ee;border-radius:10px;margin-bottom:16px;overflow:hidden;''>
  <div style=''display:flex;justify-content:space-between;align-items:center;gap:10px;padding:12px 16px;background:#f7f8fa;border-bottom:1px solid #e6e9ee;''>
    <span style=''font-size:16px;font-weight:700;color:#16202e;''>หุ้นญี่ปุ่น (JP Equity)</span>
    <span style=''display:inline-block;font-size:12px;font-weight:700;border-radius:6px;padding:2px 9px;background:#e7f4ec;border:1px solid #b6dcc4;color:#1f7a4d;''>Slightly Overweight</span>
  </div>
  <div style=''padding:14px 16px;''>
    <p><span>ภาพรวม: ตลาดหุ้นญี่ปุ่นได้รับแรงหนุนจากกลุ่มเทคโนโลยีและเซมิคอนดักเตอร์ที่ตอบสนองต่อ AI Capex อย่างต่อเนื่อง ทั้ง Advantest และ DISCO สะท้อนดีมานด์อุปกรณ์ทดสอบและอุปกรณ์ผลิตชิปขั้นสูงที่แข็งแกร่ง ในขณะที่ Shunto ปี 2026 ได้ค่าจ้างเฉลี่ยเพิ่มขึ้น 5.26% เป็นปีที่ 3 ติดต่อกันที่เกิน 5% ซึ่งช่วยหนุนกำลังซื้อภายในประเทศ</span></p>
    <p><span style=''font-weight:700;''>ปัจจัยสนับสนุน</span></p>
    <ul>
      <li><span>หาก Earnings บริษัทญี่ปุ่นออกมาดีกว่าคาดพร้อมการปรับ Guidance ขึ้น จะช่วยผ่อนคลายความกังวลต่อต้นทุนพลังงานและ Supply Chain ได้มากขึ้น ขณะที่ BOJ คงดอกเบี้ยที่ 0.75% และหากสื่อสารนโยบายได้ราบรื่น ตลาดจะมองการขึ้นดอกเบี้ยเป็นสัญญาณเศรษฐกิจแข็งแรง</span></li>
      <li><span>รัฐบาลญี่ปุ่นผลักดัน Multi-year Budget ลงทุนใน Economic Security และอุตสาหกรรมเป้าหมาย ซึ่งมีโอกาสเร่ง Earnings Revision ผ่าน CAPEX ขนาดใหญ่ ประกอบกับ Shunto ที่หนุนกำลังซื้อในประเทศต่อเนื่อง</span></li>
      <li><span>ธีม Deflation to Inflation และ De-rating to Re-rating ยังคงมีผลในระยะยาว โดย Topix Best EPS ปรับตัวขึ้นสู่ราว 220 สอดคล้องกับการเติบโตของค่าจ้างพื้นฐาน</span></li>
    </ul>
    <p><span style=''font-weight:700;''>ปัจจัยเสี่ยง</span></p>
    <ul>
      <li><span>หากราคาน้ำมันยืนเหนือ 100 ดอลลาร์ต่อบาร์เรลและค่าเงินเยนอ่อนทะลุ JPY 160 ต่อดอลลาร์ จะกดดัน Margin บริษัทญี่ปุ่นอย่างรุนแรง เนื่องจากญี่ปุ่นพึ่งพาการนำเข้าพลังงาน 87% ของอุปทานทั้งหมด และ 95% ของน้ำมันดิบมาจากตะวันออกกลาง</span></li>
      <li><span>BOJ เผชิญทางสองแพร่งระหว่างการขึ้นดอกเบี้ยเพื่อสกัดเงินเฟ้อและพยุงเงินเยน กับความเสี่ยงที่จะซ้ำเติม Supply Shock โดย BOJ ได้ปรับลดประมาณการ GDP ปี 2026 ลงเพื่อสะท้อนผลกระทบจากสงคราม</span></li>
    </ul>
    <p><span style=''font-weight:700;''>แนวโน้ม/กลยุทธ์:</span> <span>คง Slightly Overweight สำหรับระยะ 12 เดือนข้างหน้า มองเป็นโอกาสทยอยสะสมในช่วงที่ตลาดย่อตัว โดยเน้นหุ้นในห่วงโซ่ AI/Semiconductor เช่น Advantest และ DISCO ที่ตอบรับ AI Capex โดยตรง</span></p>
