insert into "monthly_asset_class_outlook" ("path", "hs_name", "week_slug", "main_title", "page_subtitle", "sub_title", "page_date", "week_start_date", "week_end_date", "cover_image", "description", "ai_summary", "body", "is_published") values ('2026-05-01-fixed-income', 'มุมมองตราสารหนี้เดือนพฤษภาคม 2569: รอความชัดเจนดอกเบี้ย ระวัง Yield ไทยขาขึ้น', '2026-05-01', 'มุมมองตราสารหนี้เดือนพฤษภาคม 2569: รอความชัดเจนดอกเบี้ย ระวัง Yield ไทยขาขึ้น', 'มุมมองการลงทุนรายเดือน — ตราสารหนี้ พฤษภาคม 2569', 'ตราสารหนี้', '2026-05-01', '2026-05-01', '2026-05-31', '{"url": "https://43844850.fs1.hubspotusercontent-na2.net/hubfs/43844850/monthly-reports/20260505_Yuanta_Monthly_Asset_Allocation_May_2026/page_040.png", "altText": "", "type": "image"}'::jsonb, 'เมื่อ Stagflation กลับมาหลอกหลอนตลาดพันธบัตรโลก และ พ.ร.ก. เงินกู้ 4 แสนล้านบาทกำลังจ่อคิวกดดัน Yield ไทย — กลยุทธ์ไหนที่นักลงทุนต้องการในเดือนนี้?', '<p><span>ตราสารหนี้โลกยังอยู่ในภาวะ Higher for longer เนื่องจากธนาคารกลางหลักเลือกตรึงดอกเบี้ยรอความชัดเจน ขณะที่ตราสารหนี้ไทยเผชิญแรงกดดันเพิ่มเติมจาก พ.ร.ก. เงินกู้และการขาดดุลงบประมาณสูงต่อเนื่อง</span></p><p><span>Yuanta CIO แนะนำ Neutral สำหรับพันธบัตรโลก และ Slightly Underweight สำหรับพันธบัตรไทย โดยเน้นช่วงอายุสั้นถึงกลาง และทยอยสะสมกองทุน UGISFX-N เมื่อ UST 10Y เกิน 4.25%</span></p>', '<h3><span>ภาพรวมตราสารหนี้</span></h3>
<p><span>ในเดือนพฤษภาคม 2569 ตราสารหนี้โลกยังคงเผชิญกับบรรยากาศของความไม่แน่นอน โดยแม้ว่าตลาดจะมีการฟื้นตัวในช่วงต้นเดือนเมษายนจากการผ่อนคลายความตึงเครียดระหว่างสหรัฐฯ – อิหร่าน แต่ความกังวลด้าน Stagflation ก็กลับมากดดันตลาดในช่วงครึ่งหลังของเดือน ธนาคารกลางหลักทั้ง FED, ECB และ BOJ ต่างเลือกแนวทาง "ตรึงดอกเบี้ย รอดูความชัดเจน" โดยหลีกเลี่ยงการดำเนินนโยบายการเงินเชิงรุก ส่งผลให้ภาพการลดดอกเบี้ยถูกเลื่อนออกไป และตลาดคาดการณ์ว่าการลดดอกเบี้ยครั้งถัดไปของ Fed จะเกิดขึ้นในการประชุมวันที่ 27 กรกฎาคม สำหรับตราสารหนี้ไทยนั้น แรงกดดันหลักมาจากฝั่งการคลัง โดยเฉพาะการขาดดุลงบประมาณปี 2569 ที่สูงถึง 860,000 ล้านบาท และความเสี่ยงเพิ่มเติมจาก พ.ร.ก. เงินกู้วงเงิน 400,000 ล้านบาท ซึ่งอาจผลักดัน TH 10Y Yield ให้ปรับตัวสูงขึ้นได้อีก</span></p>
<p><img src=''https://43844850.fs1.hubspotusercontent-na2.net/hubfs/43844850/monthly-reports/20260505_Yuanta_Monthly_Asset_Allocation_May_2026/page_040.png'' width=''1282'' height=''890'' loading=''lazy'' alt=''US Treasury 10Y Stagflation Price-In and FOMC Rate Path'' style=''height: auto; max-width: 100%; width: 1282px; margin-left: auto; margin-right: auto; display: block;''></p>
<p>&nbsp;</p>

<div style=''border:1px solid #e6e9ee;border-radius:10px;margin-bottom:16px;overflow:hidden;''>
  <div style=''display:flex;justify-content:space-between;align-items:center;gap:10px;padding:12px 16px;background:#f7f8fa;border-bottom:1px solid #e6e9ee;''>
    <span style=''font-size:16px;font-weight:700;color:#16202e;''>ตราสารหนี้โลก (Global Fixed Income)</span>
    <span style=''display:inline-block;font-size:12px;font-weight:700;border-radius:6px;padding:2px 9px;background:#eef1f5;border:1px solid #d4dbe4;color:#5b6675;''>Neutral</span>
  </div>
  <div style=''padding:14px 16px;''>
    <p><span>ภาพรวม: ตราสารหนี้โลกในเดือนพฤษภาคม 2569 อยู่ในภาวะ Higher for longer โดยธนาคารกลางหลักยังไม่มีสัญญาณลดดอกเบี้ยในระยะใกล้ ขณะที่ตลาดกำลังรอข้อมูลเงินเฟ้อจริงในช่วงปลายไตรมาส 2 ถึงต้นไตรมาส 3 เพื่อประเมินทิศทางดอกเบี้ยบน 2nd round inflation</span></p>
    <p><span style=''font-weight:700;''>ปัจจัยสนับสนุน</span></p>
    <ul>
      <li><span>ตลาดได้สะท้อนความกลัว Stagflation ไปเป็นส่วนมากแล้ว ทำให้ upside ของ Yield จากจุดนี้มีจำกัด</span></li>
      <li><span>หาก "ราคาที่อยู่อาศัยและค่าเช่า" รวมถึงค่าขนส่งไม่ปรับตัวขึ้นใน 2–3 เดือนข้างหน้า จะเป็นสัญญาณให้ Bond Yield เริ่มปรับลดลง และตราสารหนี้มีโอกาสสร้างผลตอบแทนทางราคา</span></li>
      <li><span>ตลาดคาดการณ์ว่า Fed จะเริ่มปรับลดดอกเบี้ยในการประชุมวันที่ 27 กรกฎาคม โดย Fed Funds Rate ปัจจุบันอยู่ที่ 3.75% และตลาดคาดอัตราถัดไปที่ราว 3.615%</span></li>
    </ul>
    <p><span style=''font-weight:700;''>ปัจจัยเสี่ยง</span></p>
    <ul>
      <li><span>ภาวะ Higher for longer อาจยืดยาวกว่าที่ประเมินไว้ โดย Bear case คือถึงกลางปี 2027 หรือนานกว่านั้น</span></li>
      <li><span>"เงินเฟ้อคาดหวัง (Inflation Expectation)" เร่งตัวขึ้นอาจเปิดโอกาสให้ Fed ปรับทิศทางดอกเบี้ยขึ้นในระยะ 1–3 ปี แม้โอกาสในระยะสั้นจะยังต่ำ</span></li>
      <li><span>ความตึงเครียดทางภูมิรัฐศาสตร์และความผันผวนของราคาสินค้าโภคภัณฑ์อาจหนุน 2nd round inflation ให้สูงกว่าคาด</span></li>
    </ul>
    <p><span style=''font-weight:700;''>แนวโน้ม/กลยุทธ์:</span> <span>Yuanta CIO คงคำแนะนำ Neutral สำหรับตราสารหนี้โลกใน Satellite Portfolio ระยะ 12 เดือนขึ้นไป โดยไม่แนะนำให้เก็งทิศทางดอกเบี้ยผ่านการเพิ่ม Duration สำหรับ Core Portfolio แนะนำให้ลงทุนผ่านกองทุน UGISFX-N โดยตั้ง Zone ทยอยซื้อเมื่อ UST 10Y ปรับตัวขึ้นเหนือ 4.25% และเพิ่มทุกครั้งที่ปรับขึ้นครั้งละ 0.25% เพื่อสร้าง Income ระยะยาว</span></p>
  </div>
</div>

<p>&nbsp;</p>

<div style=''border:1px solid #e6e9ee;border-radius:10px;margin-bottom:16px;overflow:hidden;''>
  <div style=''display:flex;justify-content:space-between;align-items:center;gap:10px;padding:12px 16px;background:#f7f8fa;border-bottom:1px solid #e6e9ee;''>
    <span style=''font-size:16px;font-weight:700;color:#16202e;''>ตราสารหนี้ไทย (Thailand Fixed Income)</span>
    <span style=''display:inline-block;font-size:12px;font-weight:700;border-radius:6px;padding:2px 9px;background:#fbecec;border:1px solid #f0c6c6;color:#b3372f;''>Slightly Underweight</span>
  </div>
  <div style=''padding:14px 16px;''>
    <p><span>ภาพรวม: ตราสารหนี้ไทยในเดือนพฤษภาคม 2569 เผชิญแรงกดดันจากฝั่งการคลังมากกว่าฝั่งดอกเบี้ย โดยการขาดดุลงบประมาณปี 2569 ที่ราว 860,000 ล้านบาท และกรอบปี 2570 ที่ยังขาดดุลราว 788,000 ล้านบาท ตลอดจน พ.ร.ก. เงินกู้ 400,000 ล้านบาท สะท้อนว่าปริมาณพันธบัตรรัฐบาลที่จะออกสู่ตลาดยังอยู่ในระดับสูง ซึ่งสร้างแรงกดดันต่อ TH 10Y Yield ให้ปรับตัวขึ้นต่อเนื่อง ขณะที่ Valuation ของพันธบัตรไทยยังอยู่ในระดับ Fair Value ไม่ได้มีแต้มต่อที่ชัดเจน</span></p>
    <p><img src=''https://43844850.fs1.hubspotusercontent-na2.net/hubfs/43844850/monthly-reports/20260505_Yuanta_Monthly_Asset_Allocation_May_2026/page_041.png'' width=''1282'' height=''890'' loading=''lazy'' alt=''TH 10Y Yield vs Government Deficit and Real Yield Spread'' style=''height: auto; max-width: 100%; width: 1282px; margin-left: auto; margin-right: auto; display: block;''></p>
    <p><span style=''font-weight:700;''>ปัจจัยสนับสนุน</span></p>
    <ul>
      <li><span>หากเศรษฐกิจไทยชะลอตัวมากกว่าคาดและเงินเฟ้อยังอยู่ในระดับต่ำ ตลาดอาจกลับมา price in การลดดอกเบี้ยของ ธปท. มากขึ้น หนุนราคาตราสารหนี้โดยเฉพาะช่วงอายุสั้นถึงกลาง</span></li>
      <li><span>หากรัฐบาลทยอยออกพันธบัตรแบบไม่กระจุกตัว หรือใช้วงเงินกู้ไม่เต็มจำนวนทันที แรงกดดันจาก Bond Supply อาจต่ำกว่าที่ตลาดกังวล ทำให้ TH 10Y Yield ปรับขึ้นจำกัด</span></li>
    </ul>
    <p><span style=''font-weight:700;''>ปัจจัยเสี่ยง</span></p>
    <ul>
      <li><span>ความเสี่ยงหลักอยู่ที่ Fiscal Supply เพราะการขาดดุลงบประมาณปกติยังสูง และหากรวม พ.ร.ก. เงินกู้เพิ่มเติมเต็มวงเงิน ตลาดพันธบัตรไทยต้องดูดซับ Supply ใหม่ปริมาณมาก ทำให้ Yield ลงได้จำกัดแม้เศรษฐกิจอ่อนตัว</span></li>
      <li><span>TH-US 10Y Real Yield Spread ยังอยู่ในโซน Fair Value ไม่ได้ถูกพอ ประกอบกับหนี้สาธารณะที่เข้าใกล้เพดาน 70% ของ GDP ทำให้ Valuation ไม่ได้จูงใจเมื่อเทียบกับความเสี่ยงด้านการคลัง</span></li>
      <li><span>นโยบายการคลังเชิงรุกของรัฐบาลแม้จะหนุนตลาดหุ้น แต่กลับไม่เป็นมิตรกับตลาดตราสารหนี้ เนื่องจากเพิ่มแรงกดดันด้าน Supply พันธบัตร</span></li>
    </ul>
    <p><span style=''font-weight:700;''>แนวโน้ม/กลยุทธ์:</span> <span>Yuanta CIO คงมุมมอง Slightly Underweight สำหรับตราสารหนี้ไทย กลยุทธ์ยังควรเน้นตราสารหนี้ไทยช่วงอายุสั้นถึงกลาง หลีกเลี่ยงการเพิ่ม Duration ยาวเชิงรุก โดยความน่าสนใจของพันธบัตรไทยระยะยาวจะกลับมาก็ต่อเมื่อตลาดตราสารหนี้โลกเริ่มสะท้อนภาพการลดดอกเบี้ยของสหรัฐฯ มากขึ้น ซึ่ง Yuanta CIO ประเมินว่าเร็วที่สุดคือช่วงกลางปี 2570</span></p>
  </div>
</div>

<p>&nbsp;</p>

