insert into "monthly_asset_class_outlook" ("path", "hs_name", "week_slug", "main_title", "page_subtitle", "sub_title", "page_date", "week_start_date", "week_end_date", "cover_image", "description", "ai_summary", "body", "is_published") values ('2026-06-01-equity', 'มุมมองตราสารทุนเดือนมิถุนายน 2569: คง Slightly Overweight สหรัฐฯ และญี่ปุ่น เน้นเลือกหุ้นในจีนและไทย', '2026-06-01', 'มุมมองตราสารทุนเดือนมิถุนายน 2569: คง Slightly Overweight สหรัฐฯ และญี่ปุ่น เน้นเลือกหุ้นในจีนและไทย', 'มุมมองการลงทุนรายเดือน — ตราสารทุน มิถุนายน 2569', 'ตราสารทุน', '2026-06-01', '2026-06-01', '2026-06-30', NULL, 'กำไรบริษัทเทคฯ ยังแกร่ง แต่ตลาดเริ่มแพงขึ้น — ถึงเวลาเลือกตัวให้คมขึ้น ก่อนความผันผวนรอบใหม่จะมาเยือน', '<p><span>ตลาดหุ้นสหรัฐฯ และญี่ปุ่นยังได้แรงหนุนจากการเติบโตของกำไร ขณะที่ยุโรปเผชิณความเสี่ยง Stagflation และจีนถูกกดดันจากการปรับประมาณการกำไรลง</span></p><p><span>กลยุทธ์เดือนมิถุนายน 2569 เน้น Rebalance และกระจายความเสี่ยงเข้ากลุ่ม Software ในสหรัฐฯ พร้อมเลือกลงทุนแบบทยอยสะสมในไทย</span></p>', '<h3><span>ภาพรวมตราสารทุนโลก เดือนมิถุนายน 2569</span></h3>
<p><span>ในเดือนมิถุนายน 2569 ภาพรวมตราสารทุนโลกยังคงขับเคลื่อนด้วยปัจจัยด้านกำไรบริษัทเป็นหลัก โดย Yuanta CIO คงน้ำหนักการลงทุนใน "Slightly Overweight" สำหรับสหรัฐฯ และญี่ปุ่น ขณะที่ยุโรปถูกลดน้ำหนักเป็น "Slightly Underweight" จากความเสี่ยง Stagflation และแนวโน้มการขึ้นดอกเบี้ยของ ECB ส่วนจีนและไทยอยู่ในระดับ "Neutral" โดยเน้นการเลือกลงทุนรายตัวมากกว่าการลงทุนทั้ง Index ทิศทางโดยรวมสะท้อนว่าการลงทุนในช่วง Bear Flattening จำเป็นต้องเน้นกลุ่มที่กำไรยังเติบโตและมีการปรับประมาณการต่อเนื่อง</span></p>

<p>&nbsp;</p>

<div style=''border:1px solid #e6e9ee;border-radius:10px;margin-bottom:16px;overflow:hidden;''>
  <div style=''display:flex;justify-content:space-between;align-items:center;gap:10px;padding:12px 16px;background:#f7f8fa;border-bottom:1px solid #e6e9ee;''>
    <span style=''font-size:16px;font-weight:700;color:#16202e;''>หุ้นสหรัฐฯ (US Equity)</span>
    <span style=''display:inline-block;font-size:12px;font-weight:700;border-radius:6px;padding:2px 9px;background:#e7f4ec;border:1px solid #b6dcc4;color:#1f7a4d;''>Slightly Overweight</span>
  </div>
  <div style=''padding:14px 16px;''>
    <p><span>ภาพรวม: ตลาดหุ้นสหรัฐฯ ฟื้นตัวตามผลประกอบการและทำจุดสูงสุดใหม่เหนือ 7,500 จุด โดยเม็ดเงินยังกระจุกตัวในกลุ่มที่รายงานผลประกอบการดีกว่าคาดและมีการปรับ Guidance ขึ้นต่อเนื่อง ด้าน Forward PER ปัจจุบันซื้อขายในระดับ +0.5 ถึง +0.75 SD เทียบกับค่าเฉลี่ย 5 ปี (Mean: 20.03) ซึ่งใกล้เคียงกับช่วงมุมมองเดือนพฤษภาคม</span></p>
    <p><span style=''font-weight:700;''>ปัจจัยสนับสนุน</span></p>
    <ul>
      <li><span>ผู้บริหารกลุ่มเทคโนโลยีให้ Guidance ในทางบวกสำหรับการเติบโตของกำไรแบบ Bottom-Up อย่างต่อเนื่อง สอดคล้องกับธีมการลงทุนในช่วง Bear Flattening</span></li>
      <li><span>Valuation กลับมาซื้อขายระดับ Forward PER 5 ปี บริเวณ +0.5 – 0.75 SD ซึ่งเป็นผลจากการปรับประมาณการกำไรตลาดขึ้น ไม่ใช่การเก็งกำไร</span></li>
      <li><span>หุ้นกลุ่ม Software พิสูจน์แล้วใน 1Q26 ว่า MOAT ไม่ได้ถูกกระทบจาก Claude Cowork อย่างมีนัยสำคัญ</span></li>
    </ul>
    <p><span style=''font-weight:700;''>ปัจจัยเสี่ยง</span></p>
    <ul>
      <li><span>หากกำไรกลุ่ม Technology เริ่มอ่อนตัวลง อาจทำให้ S&P 500 ยืนเหนือระดับ +1 SD ได้ยาก โดย Yuanta CIO กังวลประเด็นความต่อเนื่องของ Earnings มากกว่า Valuation</span></li>
      <li><span>เริ่มเห็นแรงเก็งกำไรบางส่วนใน Leveraged ETF ซึ่งอาจทำให้ความผันผวนสูงขึ้น แม้ Valuation ยังไม่ใช่ประเด็นหลัก</span></li>
      <li><span>ทิศทางนโยบายการเงินยังไม่เปลี่ยนแปลงมากนัก แม้เงินเฟ้อปรับขึ้นและ US 10Y แตะจุดสูงสุดใหม่ในรอบหลายเดือน โดยตลาดประเมินว่าเฟดจะไม่สามารถลดดอกเบี้ยได้ตามที่เคยสื่อสารไว้</span></li>
    </ul>
    <p><span style=''font-weight:700;''>แนวโน้ม/กลยุทธ์:</span> <span>คงคำแนะนำ Slightly Overweight สำหรับ Satellite Portfolio ระยะ 12 เดือน โดยแนะนำ Rebalance และล็อคกำไรบางส่วนในกลุ่มเซมิคอนดักเตอร์ผ่าน SMH (ETF), SCBSEMI(A) และ NVDA19 เพื่อควบคุมสัดส่วนให้อยู่ในช่วง 5–10% พร้อมกระจายความเสี่ยงเพิ่มเติมเข้าสู่กลุ่ม Software ผ่าน IGV, MSFT19, ORCL19 และ PLTR06 โดยหุ้นกลุ่มเซมิคอนดักเตอร์ยังซื้อขายบน Forward PER 22 เท่า ต่ำกว่าค่าเฉลี่ย 5 ปี</span></p>
    <p><img src=''https://43844850.fs1.hubspotusercontent-na2.net/hubfs/43844850/monthly-reports/Yuanta_Monthly_Asset_Allocation_June_2026/component_images/page_48.png'' width=''1282'' height=''890'' loading=''lazy'' alt=''S&P 500 Forward PE 5-Year Band'' style=''height: auto; max-width: 100%; width: 1282px; margin-left: auto; margin-right: auto; display: block;''></p>
  </div>
</div>

<p>&nbsp;</p>

<div style=''border:1px solid #e6e9ee;border-radius:10px;margin-bottom:16px;overflow:hidden;''>
  <div style=''display:flex;justify-content:space-between;align-items:center;gap:10px;padding:12px 16px;background:#f7f8fa;border-bottom:1px solid #e6e9ee;''>
    <span style=''font-size:16px;font-weight:700;color:#16202e;''>หุ้นยุโรป (EU Equity)</span>
    <span style=''display:inline-block;font-size:12px;font-weight:700;border-radius:6px;padding:2px 9px;background:#fbecec;border:1px solid #f0c6c6;color:#b3372f;''>Slightly Underweight</span>
  </div>
  <div style=''padding:14px 16px;''>
    <p><span>ภาพรวม: ตลาดหุ้นยุโรปฟื้นตัวได้ในเดือนพฤษภาคม แต่คุณภาพการฟื้นตัวยังไม่แข็งแรง เพราะแรงหนุนมาจากผลประกอบการเฉพาะบางกลุ่ม ขณะที่ภาพ Macro เริ่มเข้าใกล้ภาวะ Stagflation หลัง European Commission ปรับภาพเศรษฐกิจเป็นโตช้าลงแต่เงินเฟ้อสูงขึ้นจาก Energy Shock และเงินเฟ้อ Eurozone เดือนเมษายนเร่งขึ้นเป็น 3.0%</span></p>
    <p><span style=''font-weight:700;''>ปัจจัยสนับสนุน</span></p>
    <ul>
      <li><span>European blue-chips มีแนวโน้มกำไรโต 11.5% YoY ใน 1Q26 ซึ่งเป็นอัตราที่แข็งแรงสุดตั้งแต่ 4Q22 โดยกลุ่ม Energy และ Financials เป็นแรงหนุนหลัก</span></li>
      <li><span>กลุ่มกลาโหมยังได้แรงหนุนจากการเพิ่มงบความมั่นคงยุโรป กลุ่ม Grid/Data Center ได้ประโยชน์จากการลงทุนโครงข่ายไฟฟ้าและ AI Infrastructure ผ่านหุ้นอย่าง Schneider Electric และ Siemens Energy</span></li>
      <li><span>SAP, ASML และ BESI ยังเป็น Quality Growth ของยุโรปจาก Cloud Transition, Business AI และ Hybrid Bonding ประกอบกับ Chips Act 2.0 ช่วงปลายเดือนพฤษภาคมเป็น Policy Tailwind ใหม่ของกลุ่มเซมิคอนดักเตอร์ยุโรป</span></li>
    </ul>
    <p><span style=''font-weight:700;''>ปัจจัยเสี่ยง</span></p>
    <ul>
      <li><span>Energy Shock เริ่มเปลี่ยนจากความเสี่ยงเฉพาะจุดไปเป็นกรอบหลักของเศรษฐกิจยุโรป โดย European Commission คาดว่าแรงกดดันจากพลังงานจะลากต่อถึงปี 2027 ซึ่งกดทั้ง Margin และกำลังซื้อครัวเรือน</span></li>
      <li><span>Reuters poll เดือนพฤษภาคมระบุว่านักเศรษฐศาสตร์ส่วนใหญ่คาดว่า ECB จะขึ้นดอกเบี้ยในเดือนมิถุนายน และอาจขึ้นอีกอย่างน้อยหนึ่งครั้งในปีนี้ ซึ่งกด Valuation และลด Upside ของกลุ่ม Value</span></li>
      <li><span>กลุ่ม Luxury และ Auto ยังถูกกดดันจากจีน การใช้จ่ายผู้บริโภค และ Tourist Flows ที่อ่อนลง ขณะที่ Valuation ยังซื้อขายในระดับที่แพงกว่าสหรัฐฯ ในเชิงเปรียบเทียบ</span></li>
    </ul>
    <p><span style=''font-weight:700;''>แนวโน้ม/กลยุทธ์:</span> <span>คงมุมมอง Slightly Underweight ในหุ้นยุโรปสำหรับการลงทุนใน 12 เดือนข้างหน้า จากภาพความเสี่ยงที่ชัดขึ้นทั้ง Energy Shock, Stagflation Risk และโอกาสที่ ECB จะกลับมาขึ้นดอกเบี้ย ทำให้ Upside ยังค่อนข้างจำกัด</span></p>
    <p><img src=''https://43844850.fs1.hubspotusercontent-na2.net/hubfs/43844850/monthly-reports/Yuanta_Monthly_Asset_Allocation_June_2026/page_images/page_049.png'' width=''1282'' height=''890'' loading=''lazy'' alt=''EU Equity Slightly Underweight Re-rate Analysis'' style=''height: auto; max-width: 100%; width: 1282px; margin-left: auto; margin-right: auto; display: block;''></p>
  </div>
</div>

<p>&nbsp;</p>

<div style=''border:1px solid #e6e9ee;border-radius:10px;margin-bottom:16px;overflow:hidden;''>
  <div style=''display:flex;justify-content:space-between;align-items:center;gap:10px;padding:12px 16px;background:#f7f8fa;border-bottom:1px solid #e6e9ee;''>
    <span style=''font-size:16px;font-weight:700;color:#16202e;''>หุ้นญี่ปุ่น (JP Equity)</span>
    <span style=''display:inline-block;font-size:12px;font-weight:700;border-radius:6px;padding:2px 9px;background:#e7f4ec;border:1px solid #b6dcc4;color:#1f7a4d;''>Slightly Overweight</span>
  </div>
  <div style=''padding:14px 16px;''>
    <p><span>ภาพรวม: ตลาดหุ้นญี่ปุ่นเดือนพฤษภาคมได้แรงหนุนจาก Earnings มากกว่า Macro เพียงอย่างเดียว โดย GDP 1Q26 โต 2.1% Annualized ดีกว่าคาดจากส่งออกและการบริโภค ขณะที่ MUFG, Mizuho และ SMFG ทำกำไรประจำปีสูงสุดเป็นประวัติการณ์ และ Kioxia ให้ Guidance แข็งแกร่งจาก AI Memory Boom</span></p>
    <p><span style=''font-weight:700;''>ปัจจัยสนับสนุน</span></p>
    <ul>
      <li><span>Earnings Revision เริ่มกลับมาดีขึ้นจากกลุ่ม Electronics และธนาคาร หาก Momentum ของ AI/Semiconductors และ Financials ยังต่อเนื่อง Valuation อาจลดลงได้จาก Earnings Revision</span></li>
      <li><span>Shunto ปี 2026 ค่าจ้างเพิ่มเฉลี่ย 5.26% เป็นปีที่ 3 ที่เกิน 5% สนับสนุน Real Wage Growth และส่งผ่านไปยังการบริโภคในประเทศ สอดคล้องกับ Fig 3.1 ที่ค่าจ้างและ TOPIX EPS เคลื่อนไปทิศทางเดียวกัน</span></li>
      <li><span>รัฐบาล Takaichi เตรียมงบเสริมราว 3 ล้านล้านเยน เพื่ออุดหนุนค่าน้ำมัน ค่าไฟ และลดภาระค่าครองชีพ ช่วยลดแรงกดดันจากพลังงานต่อกำลังซื้อครัวเรือน</span></li>
    </ul>
    <p><span style=''font-weight:700;''>ปัจจัยเสี่ยง</span></p>
    <ul>
      <li><span>ตัวชี้วัดของ BOJ ที่ตัดผลของปัจจัยชั่วคราวและ Subsidy ออก เร่งขึ้นเป็น 2.8% ขณะที่ราคาค่าบริการระหว่างภาคธุรกิจยังโต 3.0% YoY หากราคาน้ำมันสูงขึ้นพร้อมเงินเยนอ่อน BOJ อาจต้องขึ้นดอกเบี้ยเร็วกว่าที่ตลาดคาด</span></li>
      <li><span>Toyota คาดกำไรปีปัจจุบันลดลง 20% และประเมินผลกระทบจากสงครามอิหร่านราว 4.3 พันล้านดอลลาร์ สะท้อนความเสี่ยง Earnings Downgrade ในกลุ่มที่อ่อนไหวต่อพลังงานและ Supply Chain</span></li>
      <li><span>10-year JGB Yield ขึ้นแตะ 2.8% สูงสุดตั้งแต่ปี 1996 และ 30-year Yield ขยับเหนือ 4% ทำให้ Fiscal Support อาจทำได้จำกัดขึ้นหาก Yield สูงต่อเนื่อง</span></li>
    </ul>
    <p><span style=''font-weight:700;''>แนวโน้ม/กลยุทธ์:</span> <span>คงมุมมอง Slightly Overweight ต่อหุ้นญี่ปุ่นใน 12 เดือนข้างหน้า โดยเลือกลงทุนมากขึ้นในกลุ่ม AI/Semiconductors, Financials และหุ้นที่ได้ประโยชน์จาก Domestic Demand เพราะได้แรงหนุนจาก Earnings Revision, Wage Growth และ Fiscal Support โดยตรง</span></p>
    <p><img src=''https://43844850.fs1.hubspotusercontent-na2.net/hubfs/43844850/monthly-reports/Yuanta_Monthly_Asset_Allocation_June_2026/page_images/page_050.png'' width=''1282'' height=''890'' loading=''lazy'' alt=''JP Equity Slightly Overweight BOJ Growth Analysis'' style=''height: auto; max-width: 100%; width: 1282px; margin-left: auto; margin-right: auto; display: block;''></p>
  </div>
</div>

<p>&nbsp;</p>

<div style=''border:1px solid #e6e9ee;border-radius:10px;margin-bottom:16px;overflow:hidden;''>
  <div style=''display:flex;justify-content:space-between;align-items:center;gap:10px;padding:12px 16px;background:#f7f8fa;border-bottom:1px solid #e6e9ee;''>
    <span style=''font-size:16px;font-weight:700;color:#16202e;''>หุ้นจีน (CN Equity)</span>
    <span style=''display:inline-block;font-size:12px;font-weight:700;border-radius:6px;padding:2px 9px;background:#eef1f5;border:1px solid #d4dbe4;color:#5b6675;''>Neutral</span>
  </div>
  <div style=''padding:14px 16px;''>
    <p><span>ภาพรวม: ตลาดหุ้นจีน (MSCI China) เดือนที่ผ่านมาแกว่งตัวผันผวน โดย CSI 300 ปรับขึ้นราว 2.64% ขณะที่ HSCEI ปรับลง 1.26% ส่งผลให้ MSCI China ลดลงราว 1% แม้จะมีการพบกันระหว่างผู้นำสหรัฐฯ และจีน ด้านกำไรตลาดยังน่าห่วง เพราะแม้ยอดขายโดยรวมดีกว่าคาด แต่ทิศทางกำไรต่ำกว่าคาด สะท้อนว่าจีนยังไม่สามารถควบคุมต้นทุนได้ในช่วงพลังงานสูง</span></p>
    <p><span style=''font-weight:700;''>ปัจจัยสนับสนุน</span></p>
    <ul>
      <li><span>การจัดสรรงบประมาณใหม่ตามนโยบาย AI+ หลังการประชุม Politburo ช่วงปลายเดือนเมษายน อาจเป็นแรงหนุนทางบวกต่อ Supply Chain AI ของจีน</span></li>
      <li><span>ทิศทางกลุ่มเทคโนโลยีขนาดใหญ่อย่าง Alibaba, Tencent และ JD เริ่มมีสัญญาณแย่น้อยลง จากธุรกิจ Cloud และ AI</span></li>
    </ul>
    <p><span style=''font-weight:700;''>ปัจจัยเสี่ยง</span></p>
    <ul>
      <li><span>ภาพรวมยังมีการปรับประมาณการกำไรลดลงอย่างต่อเนื่องนับตั้งแต่ปลายเดือนกุมภาพันธ์ สะท้อนว่านักวิเคราะห์กังวลกับราคาพลังงานที่สูงขึ้นจนกดดัน Margin ของบริษัท</span></li>
      <li><span>CSI 300 กลับขึ้นมาซื้อขายบริเวณ +1.5 SD และ HSCEI ซื้อขายในระดับ +1 SD กรอบ Forward P/E 5 ปี สะท้อนจากการปรับตัวขึ้นของดัชนีสวนทางกับการปรับประมาณการกำไรลดลงต่อเนื่อง</span></li>
      <li><span>หาก Sentiment ด้านราคาพลังงานยังอยู่ในระดับสูงต่อเนื่องใน 2H26 อาจทำให้ Downside ของกำไรตลาดจากการปรับลด Gross Margin มีโอกาสเกิดขึ้นได้อีก</span></li>
    </ul>
    <p><span style=''font-weight:700;''>แนวโน้ม/กลยุทธ์:</span> <span>Yuanta CIO คงคำแนะนำ Neutral สำหรับ Satellite Portfolio ระยะ 12 เดือน และแนะนำให้นักลงทุนติดตามกำไรของบริษัทจดทะเบียนอย่างใกล้ชิด สำหรับผู้ที่สนใจลงทุนหุ้นจีน ให้พิจารณาบริษัทขนาดใหญ่เป็นหลักและเป็นรายตัวมากกว่าลงทั้ง Index</span></p>
    <p><img src=''https://43844850.fs1.hubspotusercontent-na2.net/hubfs/43844850/monthly-reports/Yuanta_Monthly_Asset_Allocation_June_2026/component_images/page_51.png'' width=''1282'' height=''890'' loading=''lazy'' alt=''MSCI China Rolling Returns Jan 2025 to May 2026'' style=''height: auto; max-width: 100%; width: 1282px; margin-left: auto; margin-right: auto; display: block;''></p>
  </div>
</div>

<p>&nbsp;</p>

<div style=''border:1px solid #e6e9ee;border-radius:10px;margin-bottom:16px;overflow:hidden;''>
  <div style=''display:flex;justify-content:space-between;align-items:center;gap:10px;padding:12px 16px;background:#f7f8fa;border-bottom:1px solid #e6e9ee;''>
    <span style=''font-size:16px;font-weight:700;color:#16202e;''>หุ้นไทย (TH Equity)</span>
    <span style=''display:inline-block;font-size:12px;font-weight:700;border-radius:6px;padding:2px 9px;background:#eef1f5;border:1px solid #d4dbe4;color:#5b6675;''>Neutral</span>
  </div>
  <div style=''padding:14px 16px;''>
    <p><span>ภาพรวม: ตลาดหุ้นไทยเริ่มกลับมามีแรงหนุนจากความหวังต่อสินทรัพย์เสี่ยง หลังสถานการณ์สหรัฐฯ กับอิหร่านมีสัญญาณผ่อนคลาย โดยล่าสุด SET ปิดที่ 1,528.43 จุด เพิ่มขึ้น 0.77% ด้วยมูลค่าการซื้อขาย 5.92 หมื่นล้านบาท ผลประกอบการ 1Q26 ดีกว่าคาดมาก โดยกำไรอยู่ที่ 3.6 แสนล้านบาท เพิ่มขึ้น 59% QoQ และ 21% YoY สูงกว่าประมาณการเดิม 24% ส่งผลให้มีการปรับ EPS สิ้นปีขึ้นเป็น 95 บาทต่อหุ้น จาก 87 บาทต่อหุ้น และปรับเป้า SET Index ขึ้นเป็น 1,560 จุด จาก 1,440 จุด โดยยังอิง PER 16.5 เท่า</span></p>
    <p><span style=''font-weight:700;''>ปัจจัยสนับสนุน</span></p>
    <ul>
      <li><span>กำไรตลาดถูกปรับขึ้น และโมเมนตัมใน 2H26 ยังมีโอกาสดีขึ้นจากฐานกำไรต่ำ มาตรการกระตุ้นเศรษฐกิจของรัฐบาล และการลงทุนภาคเอกชนที่เริ่มเห็นผลบวกมากขึ้น</span></li>
      <li><span>ธีมหลักที่ให้น้ำหนัก ได้แก่ มาตรการดูแลค่าครองชีพ การลงทุน Mega Project ของภาครัฐและเอกชนเช่น Data Center แผน PDP ฉบับใหม่ เงินเฟ้อที่ทรงตัวในระดับสูง และหุ้นปันผลสม่ำเสมอ</span></li>
      <li><span>กลุ่ม Anti-Oil Play เช่น สายการบิน ท่องเที่ยว โรงไฟฟ้า บรรจุภัณฑ์ และไฟแนนซ์ ได้แรงหนุนจากราคาน้ำมันที่อ่อนตัวลง ขณะที่กลุ่มไฟแนนซ์ยังมีโอกาสฟื้นตัวเด่นจากก่อนหน้านี้ที่ฟื้นช้ากว่า Domestic Play อื่น</span></li>
    </ul>
    <p><span style=''font-weight:700;''>ปัจจัยเสี่ยง</span></p>
    <ul>
      <li><span>สถานการณ์ตะวันออกกลางและทิศทางราคาน้ำมัน หากไม่ผ่อนคลาย ราคาน้ำมันและ Bond Yield สหรัฐฯ อาจกลับมากดดันตลาด โดย SET Index มีโอกาสพักตัวลงบริเวณ 1,490 จุด บวกลบ ก่อนจะกลับทดสอบ 1,540 จุดในกรณีที่ความเสี่ยงลดลง</span></li>
      <li><span>กรอบ Valuation ค่อนข้างตึงตัว ขณะที่แนวโน้มกำไร 2Q26 ยังมีโอกาสชะลอ QoQ จาก Low Season และลดลง YoY จากฐานสูงในปีก่อน</span></li>
    </ul>
    <p><span style=''font-weight:700;''>แนวโน้ม/กลยุทธ์:</span> <span>Yuanta CIO ปรับคำแนะนำเป็น Neutral และเน้นทยอยสะสมเมื่ออ่อนตัวมากกว่าไล่ซื้อทั้งตลาด โดยหุ้นแนะนำได้แก่ CPALL, GULF, GUNKUL, GLOBAL, SCB, TIDLOR และ TRUE พร้อมไอเดียสะสม SCB จาก Dividend Yield สูง และ TIDLOR จากเงินปันผลและโครงการซื้อหุ้นคืน</span></p>
    <p><img src=''https://43844850.fs1.hubspotusercontent-na2.net/hubfs/43844850/monthly-reports/Yuanta_Monthly_Asset_Allocation_June_2026/component_images/page_52_02.png'' width=''1282'' height=''890'' loading=''lazy'' alt=''Thailand SET Forward PE 5-Year Band'' style=''height: auto; max-width: 100%; width: 1282px; margin-left: auto; margin-right: auto; display: block;''></p>
  </div>
</div>', true);
insert into "monthly_asset_class_outlook" ("path", "hs_name", "week_slug", "main_title", "page_subtitle", "sub_title", "page_date", "week_start_date", "week_end_date", "cover_image", "description", "ai_summary", "body", "is_published") values ('2026-06-01-fixed-income', 'มุมมองตราสารหนี้เดือนมิถุนายน 2569: Carry First, Duration Later — คงน้ำหนัก Neutral โลก และ Slightly Underweight ไทย', '2026-06-01', 'มุมมองตราสารหนี้เดือนมิถุนายน 2569: Carry First, Duration Later — คงน้ำหนัก Neutral โลก และ Slightly Underweight ไทย', 'มุมมองการลงทุนรายเดือน — ตราสารหนี้ มิถุนายน 2569', 'ตราสารหนี้', '2026-06-01', '2026-06-01', '2026-06-30', NULL, 'ภาวะ Bear Flattening ยังครองตลาด ขณะที่เงินเฟ้อกดผลตอบแทนตราสารหนี้ไทย — กลยุทธ์ Carry First, Duration Later คือคำตอบของเดือนนี้', '<p><span>ตราสารหนี้โลกอยู่ในภาวะ Bear Flattening โดย CME ปรับจากการคาดการณ์ลดดอกเบี้ยเป็นขึ้นดอกเบี้ยในปี 2027 ขณะที่ตราสารหนี้ไทยเผชิญแรงกดดันจากเงินเฟ้อและ fiscal supply ทำให้ผลตอบแทน TH 10Y ที่ 2.26% ยังไม่น่าสนใจเพียงพอ</span></p><p><span>Yuanta CIO แนะนำกลยุทธ์ Carry First, Duration Later เน้น short-to-intermediate duration คุณภาพสูง และทยอยลงทุนผ่านกองทุน UGISFX-N เมื่อ UST 10Y ปรับขึ้นเหนือ 4.25%</span></p>', '<h3><span>ภาพรวมตราสารหนี้ เดือนมิถุนายน 2569</span></h3>
<p><span>ตราสารหนี้โลกในเดือนพฤษภาคม 2569 ที่ผ่านมามีความผันผวนต่อเนื่อง โดย US 10Y Treasury ปรับตัวขึ้นทำจุดสูงสุดใหม่ก่อนจะย่อตัวกลับมาอยู่ในระดับเดิมของต้นเดือน อันเนื่องมาจากความกังวลด้านเงินเฟ้อที่เร่งตัวขึ้นจากต้นทุนราคาพลังงาน ภาพรวมกราฟอัตราผลตอบแทนยังอยู่ในลักษณะ Bear Flattening ซึ่ง Yuanta CIO เคยเตือนไว้ และปัจจุบันสถานการณ์ดังกล่าวได้เกิดขึ้นจริงแล้ว สำหรับเดือนมิถุนายน 2569 Yuanta CIO คงกลยุทธ์หลัก "Carry First, Duration Later" โดยเน้นรับดอกเบี้ยระยะสั้นในระดับสูง และเลือก short-to-intermediate duration พร้อมคุณภาพเครดิตสูง</span></p>

<p><img src=''https://43844850.fs1.hubspotusercontent-na2.net/hubfs/43844850/monthly-reports/Yuanta_Monthly_Asset_Allocation_June_2026/page_images/page_053.png'' width=''1282'' height=''890'' loading=''lazy'' alt=''Next 12M Return During Bear Flattening'' style=''height: auto; max-width: 100%; width: 1282px; margin-left: auto; margin-right: auto; display: block;''></p>

<p>&nbsp;</p>

<div style=''border:1px solid #e6e9ee;border-radius:10px;margin-bottom:16px;overflow:hidden;''>
  <div style=''display:flex;justify-content:space-between;align-items:center;gap:10px;padding:12px 16px;background:#f7f8fa;border-bottom:1px solid #e6e9ee;''>
    <span style=''font-size:16px;font-weight:700;color:#16202e;''>ตราสารหนี้โลก (Global Fixed Income)</span>
    <span style=''display:inline-block;font-size:12px;font-weight:700;border-radius:6px;padding:2px 9px;background:#eef1f5;border:1px solid #d4dbe4;color:#5b6675;''>Neutral</span>
  </div>
  <div style=''padding:14px 16px;''>
    <p><span>ภาพรวม: ตลาดตราสารหนี้โลกยังเผชิญความผันผวนในภาวะ Bear Flattening โดย ECB ส่งสัญญาณพลิกกลับมาขึ้นดอกเบี้ยในช่วงเดือนกรกฎาคม เนื่องจากเงินเฟ้อเร่งตัว ขณะที่ Fed และ BOJ ยังคงอยู่ในโหมด Wait and See และตลาดผ่าน CME ได้ปรับมุมมองจากการคาดการณ์ลดดอกเบี้ยมาเป็นการขึ้นดอกเบี้ยในปี 2027 แล้ว</span></p>
    <p><span style=''font-weight:700;''>ปัจจัยสนับสนุน</span></p>
    <ul>
      <li><span>ตลาดได้สะท้อนความกังวลด้าน Stagflation ไปเป็นส่วนมากแล้ว และเงินเฟ้อจริงยังต้องรอช่วงปลายไตรมาส 2 ถึงต้นไตรมาส 3 เพื่อสรุปทิศทางดอกเบี้ยของ Fed</span></li>
      <li><span>หาก Kevin Warsh ส่งสัญญาณนำ Trimmed Mean PCE มาใช้เป็นปัจจัยกำหนดดอกเบี้ย จะทำให้ความจำเป็นในการขึ้นดอกเบี้ยในปี 2027 หายไปทันที และตลาดตราสารหนี้อาจพลิกกลับได้ทันที</span></li>
      <li><span>ในภาวะ Bear Flattening ผลตอบแทนเฉลี่ย 12 เดือนข้างหน้าอยู่ที่ 0.834% ซึ่งยังเป็นบวก แม้จะเป็นระดับต่ำสุดในบรรดาสี่ระบอบ Yield Curve (Bull Steepening 8.545%, Bull Flattening 5.931%, Bear Steepening 3.043%)</span></li>
    </ul>
    <p><span style=''font-weight:700;''>ปัจจัยเสี่ยง</span></p>
    <ul>
      <li><span>กรณีเลวร้ายสุดในภาวะ Bear Flattening คือ Fed อาจพลิกกลับมาขึ้นดอกเบี้ย ซึ่งจะกดดันการลงทุนตราสารหนี้โดยรวม</span></li>
      <li><span>หากดอกเบี้ยอยู่ในระดับสูงยาวนานและกดดันความสามารถในการชำระหนี้ใน Private Credit อาจทำให้ Credit spread โดยรวมกว้างขึ้น ภายใต้แนวทางการควบคุมสภาพคล่องส่วนเกินของ Kevin Warsh</span></li>
    </ul>
    <p><span style=''font-weight:700;''>แนวโน้ม/กลยุทธ์:</span> <span>Yuanta CIO คงคำแนะนำ Neutral สำหรับ Satellite Portfolio ระยะ 12 เดือนขึ้นไป ด้วยกลยุทธ์ Carry First, Duration Later — เน้น short-to-intermediate duration (3–5 ปี), high quality credit และ carry income โครงสร้างพอร์ตแบบ Defensive Barbell เอียงไปทาง short-end และ intermediate สำหรับ Core Portfolio แนะนำลงทุนผ่านกองทุน UGISFX-N โดยทยอยลงทุนเมื่อ UST 10Y ปรับตัวขึ้นเหนือ 4.25% และทยอยเพิ่มทุกครั้งที่ yield เพิ่มขึ้นครั้งละ 0.25% เพื่อสร้าง income ระยะยาว</span></p>
  </div>
</div>

<p>&nbsp;</p>

<div style=''border:1px solid #e6e9ee;border-radius:10px;margin-bottom:16px;overflow:hidden;''>
  <div style=''display:flex;justify-content:space-between;align-items:center;gap:10px;padding:12px 16px;background:#f7f8fa;border-bottom:1px solid #e6e9ee;''>
    <span style=''font-size:16px;font-weight:700;color:#16202e;''>ตราสารหนี้ไทย (TH Fixed Income)</span>
    <span style=''display:inline-block;font-size:12px;font-weight:700;border-radius:6px;padding:2px 9px;background:#fbecec;border:1px solid #f0c6c6;color:#b3372f;''>Slightly Underweight</span>
  </div>
  <div style=''padding:14px 16px;''>
    <p><span>ภาพรวม: ตราสารหนี้ไทยยังเผชิญแรงกดดันจากเงินเฟ้อที่กลับมากัดกร่อนผลตอบแทนที่แท้จริง โดยเงินเฟ้อไทยพุ่งแตะเหนือ 3% ในเดือนเมษายน 2569 ขณะที่ TH 10Y yield ณ ปัจจุบันอยู่ที่ประมาณ 2.26% ซึ่ง Yuanta CIO มองว่ายังไม่น่าสนใจพอเมื่อเทียบกับระดับเงินเฟ้อที่เร่งตัวขึ้น</span></p>
    <p><span style=''font-weight:700;''>ปัจจัยสนับสนุน</span></p>
    <ul>
      <li><span>หากรัฐบาลไม่ได้ใช้วงเงินกู้ตาม พ.ร.ก. เงินกู้ 4 แสนล้านบาทเต็มจำนวนในทันที หรือทยอยออกพันธบัตรแบบไม่กระจุกตัว แรงกดดันจาก bond supply อาจต่ำกว่าที่ตลาดกังวล และ TH 10Y yield อาจปรับขึ้นได้อย่างจำกัด</span></li>
      <li><span>ส่วนที่เหลือของ พ.ร.ก. เงินกู้ราว 2 แสนล้านบาท หากถูกนำมาใช้ลดหย่อนค่าครองชีพ (คล้ายที่ญี่ปุ่นดำเนินการในช่วงเมษายน–พฤษภาคม) จะช่วยลดเงินเฟ้อและทำให้ระดับผลตอบแทน TH 10Y กลับมาน่าสนใจอีกครั้ง</span></li>
    </ul>
    <p><span style=''font-weight:700;''>ปัจจัยเสี่ยง</span></p>
    <ul>
      <li><span>ความเสี่ยงหลักอยู่ที่ fiscal supply เพราะการขาดดุลปกติยังสูง และหากรวม พ.ร.ก. เงินกู้เพิ่มเติม ตลาดพันธบัตรไทยต้องดูดซับ supply ใหม่มากขึ้น ซึ่งอาจจำกัดโอกาสที่ yield จะปรับลดลง แม้เศรษฐกิจอ่อนตัว</span></li>
      <li><span>TH-US 10Y Real yield spread สะท้อนว่าตราสารหนี้ไทยอยู่ในระดับ Expensive เมื่อเทียบกับสหรัฐฯ โดยเปรียบเทียบ โดย real yield spread ปัจจุบันอยู่ใกล้แนว +1SD ของค่าเฉลี่ยระยะยาว</span></li>
      <li><span>BOT มี policy space จำกัด และเงินเฟ้อที่อยู่ในระดับสูงทำให้โอกาสลดดอกเบี้ยในช่วงถัดจากนี้ค่อนข้างยาก</span></li>
      <li><span>นโยบายกระตุ้นเศรษฐกิจแม้จะเป็นบวกต่อตลาดหุ้น แต่ไม่ได้เป็นมิตรกับตลาดตราสารหนี้</span></li>
    </ul>
    <p><span style=''font-weight:700;''>แนวโน้ม/กลยุทธ์:</span> <span>Yuanta CIO คงมุมมอง Slightly Underweight ต่อ Thailand Fixed Income กลยุทธ์ยังควรเน้นตราสารหนี้ไทยช่วงอายุสั้นถึงกลาง (short-to-intermediate) มากกว่าการเพิ่ม duration ยาวเชิงรุก โดยประเมินว่าความน่าสนใจของตราสารหนี้ไทยจะกลับมาก็ต่อเมื่อตลาดตราสารหนี้โลกเริ่มสะท้อนภาพการลดดอกเบี้ยของสหรัฐฯ มากขึ้น</span></p>
    <p><img src=''https://43844850.fs1.hubspotusercontent-na2.net/hubfs/43844850/monthly-reports/Yuanta_Monthly_Asset_Allocation_June_2026/page_images/page_054.png'' width=''1282'' height=''890'' loading=''lazy'' alt=''Thailand Inflation Impact on Fixed Income Return'' style=''height: auto; max-width: 100%; width: 1282px; margin-left: auto; margin-right: auto; display: block;''></p>
  </div>
</div>', true);
insert into "monthly_asset_class_outlook" ("path", "hs_name", "week_slug", "main_title", "page_subtitle", "sub_title", "page_date", "week_start_date", "week_end_date", "cover_image", "description", "ai_summary", "body", "is_published") values ('2026-06-01-foreign-fixed-income-portfolio', 'พอร์ตตราสารหนี้ต่างประเทศเดือนมิถุนายน 2569: กลยุทธ์ Defensive Barbell รับดอกเบี้ยลดช้า', '2026-06-01', 'พอร์ตตราสารหนี้ต่างประเทศเดือนมิถุนายน 2569: กลยุทธ์ Defensive Barbell รับดอกเบี้ยลดช้า', 'มุมมองการลงทุนรายเดือน — พอร์ตตราสารหนี้ต่างประเทศ มิถุนายน 2569', 'พอร์ตตราสารหนี้ต่างประเทศ', '2026-06-01', '2026-06-01', '2026-06-30', NULL, 'เมื่อดอกเบี้ยลดช้ากว่าที่คาด พอร์ต Defensive Barbell ของ Yuanta ตอบโจทย์ด้วย Carry Yield 4.01% บนเครดิตคุณภาพสูงระยะสั้นถึงกลาง — ทั้งรับกระแสดอกเบี้ยและยังลุ้น Capital Gain ได้พร้อมกัน', '<p><span>Yuanta แนะนำกลยุทธ์ Defensive Barbell โดยจัดพอร์ตพันธบัตรเอกชนคุณภาพสูงระยะสั้นถึงกลางเฉลี่ย 1.89 ปี ให้ YTM รวม 4.01% เหนือพันธบัตรรัฐบาลสหรัฐฯ อายุ 2 ปี</span></p><p><span>พอร์ตประกอบด้วย Hyundai Capital America (60%), Broadcom (20%) และ 7-Eleven (20%) ทุกตัวได้รับการจัดอันดับเครดิตระดับ Investment Grade</span></p>', '<h3><span>ภาพรวมพอร์ตตราสารหนี้ต่างประเทศ</span></h3>
<p><span>ในเดือนมิถุนายน 2569 Yuanta นำเสนอพอร์ตตราสารหนี้ต่างประเทศภายใต้กลยุทธ์ Defensive Barbell ซึ่งออกแบบมาเพื่อรองรับสภาวะ Bear Flattening หรือสภาพแวดล้อมที่ดอกเบี้ยปรับลดลงช้ากว่าที่ตลาดคาดการณ์ไว้ พอร์ตเน้นพันธบัตรเอกชนคุณภาพสูงระดับ Investment Grade อายุเฉลี่ย 1.89 ปี และให้ผลตอบแทน YTM รวม 4.01% ซึ่งสูงกว่าพันธบัตรรัฐบาลสหรัฐฯ อายุ 2 ปี ข้อมูล ณ วันที่ 29 พฤษภาคม 2569</span></p>
<p><span>แนวคิดหลักของพอร์ตนี้แบ่งออกเป็น 4 เสาหลัก ได้แก่ (1) Defensive Barbell — จัดพอร์ตผสม Duration สั้นกับระยะกลางเพื่อรับดอกเบี้ยในสภาพแวดล้อมที่ดอกเบี้ยลดช้า (2) Carry First — เน้น Yield สูงบนบริษัทคุณภาพดีที่มีความสามารถชำระหนี้ระยะยาว (3) Duration Later — อายุเฉลี่ยของพอร์ต 1.89 ปีช่วยจำกัดความเสี่ยงด้านดอกเบี้ย และ (4) High Flexibility — หากดอกเบี้ยลดเร็วกว่าคาด นักลงทุนยังสามารถได้รับ Capital Gain เพิ่มเติมได้</span></p>

<p>&nbsp;</p>

<div style=''border:1px solid #e6e9ee;border-radius:10px;margin-bottom:16px;overflow:hidden;''>
  <div style=''display:flex;justify-content:space-between;align-items:center;gap:10px;padding:12px 16px;background:#f7f8fa;border-bottom:1px solid #e6e9ee;''>
    <span style=''font-size:16px;font-weight:700;color:#16202e;''>Hyundai Capital America — HYNMTR 1.8 01/10/28 (US44891CBT99)</span>
    <span style=''display:inline-block;font-size:12px;font-weight:700;border-radius:6px;padding:2px 9px;background:#e7f4ec;border:1px solid #b6dcc4;color:#1f7a4d;''>Overweight</span>
  </div>
  <div style=''padding:14px 16px;''>
    <p><span>ภาพรวม: Hyundai Capital America คือบริษัทสินเชื่อยานยนต์ในเครือ Hyundai Motor Group และเป็นหนึ่งใน 10 บริษัทสินเชื่อรถยนต์รายใหญ่ของสหรัฐฯ ให้บริการสินเชื่อรถยนต์ ลีสซิ่ง และสินเชื่อแก่ตัวแทนจำหน่าย เพื่อสนับสนุนการจำหน่ายรถยนต์ Hyundai, Kia และ Genesis พันธบัตรรุ่นนี้มีน้ำหนักสูงสุดในพอร์ตที่ 60% สะท้อนถึงความเป็น Core Holding หลักของกลยุทธ์</span></p>
    <p><span style=''font-weight:700;''>รายละเอียดตราสาร</span></p>
    <div data-hs-responsive-table=''true'' style=''overflow-x: auto; max-width: 100%; width: 100%; margin-left: auto; margin-right: auto;''>
    <table style=''width: 100%; border-collapse: collapse; table-layout: fixed; border: 1px solid #99acc2;''>
    <tbody>
      <tr>
        <td style=''padding: 4px; background-color: #a2603c; text-align: center;''><span style=''color: #ffffff;''>น้ำหนัก</span></td>
