insert into "monthly_asset_class_outlook" ("path", "hs_name", "week_slug", "main_title", "page_subtitle", "sub_title", "page_date", "week_start_date", "week_end_date", "cover_image", "description", "ai_summary", "body", "is_published") values ('2026-07-01-equity', 'มุมมองตราสารทุนเดือนกรกฎาคม 2569: คงน้ำหนัก US และญี่ปุ่น เลือกสะสมหุ้นไทยเมื่ออ่อนตัว', '2026-07-01', 'มุมมองตราสารทุนเดือนกรกฎาคม 2569: คงน้ำหนัก US และญี่ปุ่น เลือกสะสมหุ้นไทยเมื่ออ่อนตัว', 'มุมมองการลงทุนรายเดือน — ตราสารทุน กรกฎาคม 2569', 'ตราสารทุน', '2026-07-01', '2026-07-01', '2026-07-31', NULL, 'ตลาดหุ้นโลกเดือนกรกฎาคมนี้มาพร้อมจุดเปลี่ยนสำคัญ — ใครควรสะสม ใครควรถือน้ำหนักเดิม และใครควรระวัง? Yuanta CIO ชี้ทิศทางครบทุกภูมิภาค', '<p><span>Yuanta CIO คงน้ำหนัก Slightly Overweight ในหุ้นสหรัฐฯ และญี่ปุ่น โดยเน้นกลุ่มเซมิคอนดักเตอร์และ AI เป็นหลัก ขณะที่หุ้นยุโรปถูกปรับลดเป็น Slightly Underweight จาก valuation ที่แพงและการปรับกำไรที่อ่อนแอ</span></p><p><span>หุ้นจีนคงที่ Neutral รอสัญญาณกำไรผ่านจุดต่ำสุด ส่วนหุ้นไทยปรับเป็น Neutral แนะนำทยอยสะสมเมื่ออ่อนตัวในหุ้นที่มีปัจจัยพื้นฐานรองรับ</span></p>', '<h3><span>ภาพรวมตราสารทุน</span></h3><p><span>ในเดือนกรกฎาคม 2569 Yuanta CIO คงน้ำหนัก Slightly Overweight ในหุ้นสหรัฐฯ และญี่ปุ่น โดยเน้นกลุ่มเซมิคอนดักเตอร์และ AI infrastructure เป็นแกนหลักของ Satellite portfolio ขณะที่หุ้นยุโรปถูกปรับลดน้ำหนักเป็น Slightly Underweight เนื่องจาก valuation เทียบสหรัฐฯ อยู่ในโซนแพงและการปรับประมาณการกำไรยังอ่อนแอกว่าโดยเปรียบเทียบ หุ้นจีนคงที่ Neutral รอยืนยันว่ากำไรผ่านจุดต่ำสุดแล้ว และหุ้นไทยถูกปรับเป็น Neutral พร้อมคำแนะนำทยอยสะสมเมื่ออ่อนตัวมากกว่าการไล่ซื้อทั้งตลาด</span></p><p>&nbsp;</p><div style=''border:1px solid #e6e9ee;border-radius:10px;margin-bottom:16px;overflow:hidden;''><div style=''display:flex;justify-content:space-between;align-items:center;gap:10px;padding:12px 16px;background:#f7f8fa;border-bottom:1px solid #e6e9ee;''><span style=''font-size:16px;font-weight:700;color:#16202e;''>หุ้นสหรัฐฯ (US Equity)</span><span style=''display:inline-block;font-size:12px;font-weight:700;border-radius:6px;padding:2px 9px;background:#e7f4ec;border:1px solid #b6dcc4;color:#1f7a4d;''>Slightly Overweight</span></div><div style=''padding:14px 16px;''><p><span>ภาพรวม: ตลาดหุ้นสหรัฐฯ แกว่งตัวผันผวนในกรอบ 7,200–7,500 จุดตลอดเดือนมิถุนายนที่ผ่านมา หลังตลาดขาดปัจจัยบวกใหม่ โดยการเคลื่อนไหวส่วนใหญ่ขึ้นอยู่กับปัจจัยมหภาครายวัน ทั้งประเด็นสงครามอิหร่าน-สหรัฐฯ และการเข้ารับตำแหน่งของประธานเฟดคนใหม่ Kevin Warsh ที่สร้างความผันผวนตามที่ Yuanta CIO ประเมินไว้ ประกอบกับ Dot plot ที่ Hawkish มากขึ้นและการสื่อสารที่น้อยลง</span></p><p><span style=''font-weight:700;''>ปัจจัยสนับสนุน</span></p><ul><li><span>ผู้บริหารในกลุ่มเทคโนโลยีให้ Guidance เชิงบวกสำหรับการเติบโตของกำไรตลาดแบบ Bottom-Up อย่างต่อเนื่อง โดย Positive Guidance ใน 2Q26 อยู่สูงกว่าค่าเฉลี่ย 5 ปีและ 10 ปี</span></li><li><span>Valuation ปรับมาซื้อขายบน forward PER ระดับค่าเฉลี่ย 5 ปี ทำให้เป็นจังหวะทยอยสะสมในกลุ่มเซมิคอนดักเตอร์สหรัฐฯ</span></li><li><span>ช่วงการรายงานผลประกอบการ 2Q26 มีแนวโน้มให้กลุ่มเทคโนโลยีเป็นตัวขับเคลื่อนกำไรตลาดต่อเนื่อง</span></li></ul><p><span style=''font-weight:700;''>ปัจจัยเสี่ยง</span></p><ul><li><span>หากกำไรกลุ่ม Technology อ่อนตัวลงจาก CAPEX ของกลุ่ม Hyperscaler ที่ชะลอตัว อาจทำให้หุ้นกลุ่มนี้เสี่ยงถูก De-rating ในระยะสั้น</span></li><li><span>Yuanta CIO เริ่มเห็นแรงเก็งกำไรบางส่วนใน Leveraged ETF ซึ่งอาจทำให้ความผันผวนยังสูงแม้ valuation จะไม่ใช่ประเด็นหลัก</span></li></ul><p><span style=''font-weight:700;''>แนวโน้ม/กลยุทธ์:</span> <span>แนะนำ Rebalance และล็อคกำไรบางส่วนในกลุ่มเซมิคอนดักเตอร์เพื่อควบคุมสัดส่วนให้อยู่ในช่วง 5–10% และกระจายความเสี่ยงเพิ่มเติมเข้ากลุ่ม Software โดยอาศัยจังหวะที่ตลาดแกว่งตัวปรับฐานเป็นจังหวะสะสม ทั้งนี้หุ้น NVDA19 ยังซื้อขายบน forward PER 22 เท่า ต่ำกว่าค่าเฉลี่ย 5 ปี สินทรัพย์ที่แนะนำ ได้แก่ SMH (ETF), SCBSEMI(A), NVDA19, IGV, MSFT19, ORCL19 และ PLTR06</span></p><p><img src="https://43844850.fs1.hubspotusercontent-na2.net/hubfs/43844850/monthly-reports/2026-07-01/images/page_45.png" width=''1282'' height=''890'' loading=''lazy'' alt=''Global Equity Forward PE Band Comparison'' style=''height: auto; max-width: 100%; width: 1282px; margin-left: auto; margin-right: auto; display: block;''></p><p style=''text-align: center;''><span style=''font-size: 12px; color: #6b7280;''>รูป: Global Equity Forward PE Band Comparison</span></p></div></div><p>&nbsp;</p><div style=''border:1px solid #e6e9ee;border-radius:10px;margin-bottom:16px;overflow:hidden;''><div style=''display:flex;justify-content:space-between;align-items:center;gap:10px;padding:12px 16px;background:#f7f8fa;border-bottom:1px solid #e6e9ee;''><span style=''font-size:16px;font-weight:700;color:#16202e;''>หุ้นยุโรป (EU Equity)</span><span style=''display:inline-block;font-size:12px;font-weight:700;border-radius:6px;padding:2px 9px;background:#fbecec;border:1px solid #f0c6c6;color:#b3372f;''>Slightly Underweight</span></div><div style=''padding:14px 16px;''><p><span>ภาพรวม: ตลาดหุ้นยุโรปฟื้นตัวต่อในเดือนมิถุนายน โดยแรงกดดันจากราคาพลังงานและสงครามตะวันออกกลางเริ่มคลายลงในช่วงปลายเดือน ขณะที่หุ้นเทคโนโลยี กลุ่ม AI infrastructure และธนาคารบางส่วนช่วยหนุนตลาด อย่างไรก็ดี ECB ขึ้นดอกเบี้ยในเดือนมิถุนายนเพื่อสกัดเงินเฟ้อจากพลังงาน และปรับประมาณการเงินเฟ้อขึ้น ทำให้นโยบายการเงินยังไม่กลับเป็น tailwind เต็มตัว</span></p><p><span style=''font-weight:700;''>ปัจจัยสนับสนุน</span></p><ul><li><span>เงินเฟ้อยูโรโซนเดือนมิถุนายนลดลงมาอยู่ที่ 2.8% จาก 3.2% ในเดือนพฤษภาคม โดยเยอรมนี ฝรั่งเศส และอิตาลีชะลอลงมากกว่าคาดจากราคาพลังงานที่ลดลง ลดความจำเป็นที่ ECB จะต้องเร่งขึ้นดอกเบี้ยต่อ</span></li><li><span>Sector leadership กว้างขึ้นจาก AI infrastructure, semiconductor, grid/data center, ธนาคาร และกลาโหม โดย Chips Act 2.0 เป็น policy tailwind ใหม่ของกลุ่มเซมิคอนดักเตอร์ และ UK Defence Investment Plan วางเป้าเพิ่มงบเป็นเกือบ £80bn ต่อปีภายใน 2029 และ 2.7% ของ GDP</span></li></ul><p><span style=''font-weight:700;''>ปัจจัยเสี่ยง</span></p><ul><li><span>ECB ขึ้นดอกเบี้ยแล้วและยังประเมินว่าเงินเฟ้อปี 2026–2027 จะสูงกว่าที่เคยคาด หากราคาน้ำมันกลับมาปรับขึ้นจากความเสี่ยงตะวันออกกลาง ECB อาจต้องคงท่าทีเข้มงวดนานกว่าที่ตลาดหวัง</span></li><li><span>การปรับขึ้นของตลาดในเดือนมิถุนายนยังพึ่งพากลุ่มนำค่อนข้างชัด ขณะที่ luxury และ auto ยังถูกกดดันจากจีนและ demand โลกที่ไม่แข็งแรงพอ</span></li><li><span>Valuation เมื่อเทียบกับสหรัฐฯ อยู่ในโซนแพง ขณะที่การปรับประมาณการกำไรยังอ่อนกว่าโดยเปรียบเทียบ</span></li></ul><p><span style=''font-weight:700;''>แนวโน้ม/กลยุทธ์:</span> <span>คงมุมมอง Slightly Underweight ในหุ้นยุโรปสำหรับการลงทุนในอีก 12 เดือนข้างหน้า</span></p><p><img src="https://43844850.fs1.hubspotusercontent-na2.net/hubfs/43844850/monthly-reports/2026-07-01/images/page_046.png" width=''1282'' height=''890'' loading=''lazy'' alt=''EU Equity Slightly Underweight Strategy Overview'' style=''height: auto; max-width: 100%; width: 1282px; margin-left: auto; margin-right: auto; display: block;''></p><p style=''text-align: center;''><span style=''font-size: 12px; color: #6b7280;''>รูป: EU Equity Slightly Underweight Strategy Overview</span></p></div></div><p>&nbsp;</p><div style=''border:1px solid #e6e9ee;border-radius:10px;margin-bottom:16px;overflow:hidden;''><div style=''display:flex;justify-content:space-between;align-items:center;gap:10px;padding:12px 16px;background:#f7f8fa;border-bottom:1px solid #e6e9ee;''><span style=''font-size:16px;font-weight:700;color:#16202e;''>หุ้นญี่ปุ่น (JP Equity)</span><span style=''display:inline-block;font-size:12px;font-weight:700;border-radius:6px;padding:2px 9px;background:#e7f4ec;border:1px solid #b6dcc4;color:#1f7a4d;''>Slightly Overweight</span></div><div style=''padding:14px 16px;''><p><span>ภาพรวม: ตลาดหุ้นญี่ปุ่นเดือนมิถุนายนยังได้แรงหนุนจาก earnings revision ที่เริ่มฟื้น แม้ TOPIX ซื้อขายแพงเมื่อเทียบกับ ACWI ex U.S. โดยแรงหนุนหลักยังมาจาก AI/Semiconductors และ financials ขณะที่ภาพเศรษฐกิจจริงดีขึ้นจากการบริโภคและการส่งออก รัฐบาลปรับมุมมองเศรษฐกิจเดือนมิถุนายนเป็นบวกขึ้น ด้านค่าจ้าง real wage เดือนเมษายนโตต่อเนื่องและ Shunto ปี 2026 ยังสูงกว่า 5% เป็นปีที่ 3 ติดต่อกัน</span></p><p><span style=''font-weight:700;''>ปัจจัยสนับสนุน</span></p><ul><li><span>3m earnings revision เริ่มกลับมาดีขึ้น ลดความเสี่ยงที่ตลาดจะถูกมองว่าแพงจาก multiple expansion เพียงอย่างเดียว หาก earnings momentum ในกลุ่ม AI/Semiconductors และ financials ต่อเนื่อง valuation มีโอกาสถูกลดลงผ่าน EPS ที่ปรับขึ้น</span></li><li><span>รัฐบาล Takaichi เปิด policy blueprint ใหม่เน้น multi-year investment ในอุตสาหกรรมยุทธศาสตร์ เช่น AI, semiconductors และ space พร้อมเป้าหมายดึงเงินลงทุนภาครัฐและเอกชนมากกว่า 370 ล้านล้านเยนภายใน FY2040</span></li><li><span>TOPIX EPS และ wage growth เดินในทิศทางเดียวกัน สนับสนุน thesis ว่ากำลังซื้อและกำไรบริษัทญี่ปุ่นยังมีโอกาสเดินต่อพร้อมกัน โดย TOPIX Best EPS ล่าสุดฟื้นขึ้นสู่ระดับ 235</span></li></ul><p><span style=''font-weight:700;''>ปัจจัยเสี่ยง</span></p><ul><li><span>BOJ ขึ้นดอกเบี้ยเป็น 1.0% ในเดือนมิถุนายน ซึ่งเป็นระดับสูงสุดในรอบ 31 ปี และส่งสัญญาณว่ายังต้องจับตาเงินเฟ้อที่อาจสูงกว่าเป้าหมาย ทำให้ตลาดต้องประเมินความเสี่ยง policy mistake มากขึ้น</span></li><li><span>เงินเยนอ่อนลงแตะระดับต่ำสุดในรอบ 40 ปีใกล้ 163 เยนต่อดอลลาร์ ทำให้ต้นทุนนำเข้าและความเสี่ยงแทรกแซงค่าเงินกลับมา ขณะที่ JGB yield ยังอยู่ระดับสูง</span></li></ul><p><span style=''font-weight:700;''>แนวโน้ม/กลยุทธ์:</span> <span>คงมุมมอง Slightly Overweight ต่อหุ้นญี่ปุ่นใน 12 เดือนข้างหน้า โดยเน้น financials และหุ้น domestic demand ที่ได้ประโยชน์จาก wage growth ที่เติบโตต่อเนื่อง และกลุ่ม AI/Semiconductors ที่ได้ประโยชน์จากความต้องการ AI ที่แข็งแกร่ง พร้อมแรงสนับสนุนจากนโยบายการคลังระยะยาว</span></p><p><img src="https://43844850.fs1.hubspotusercontent-na2.net/hubfs/43844850/monthly-reports/2026-07-01/images/page_047.png" width=''1282'' height=''890'' loading=''lazy'' alt=''Japan Equity Slightly Overweight BOJ Risk'' style=''height: auto; max-width: 100%; width: 1282px; margin-left: auto; margin-right: auto; display: block;''></p><p style=''text-align: center;''><span style=''font-size: 12px; color: #6b7280;''>รูป: Japan Equity Slightly Overweight BOJ Risk</span></p></div></div><p>&nbsp;</p><div style=''border:1px solid #e6e9ee;border-radius:10px;margin-bottom:16px;overflow:hidden;''><div style=''display:flex;justify-content:space-between;align-items:center;gap:10px;padding:12px 16px;background:#f7f8fa;border-bottom:1px solid #e6e9ee;''><span style=''font-size:16px;font-weight:700;color:#16202e;''>หุ้นจีน (CN Equity)</span><span style=''display:inline-block;font-size:12px;font-weight:700;border-radius:6px;padding:2px 9px;background:#eef1f5;border:1px solid #d4dbe4;color:#5b6675;''>Neutral</span></div><div style=''padding:14px 16px;''><p><span>ภาพรวม: เศรษฐกิจจีนล่าสุดสะท้อนภาพ two-speed economy ชัดเจนมากขึ้น โดยภาคการผลิตเริ่มกลับมาขยายตัว แต่การบริโภคในประเทศและอสังหาริมทรัพย์ยังเป็นจุดอ่อนหลัก PMI ภาคการผลิตเดือนมิถุนายนอยู่ที่ 50.3 กลับมาเหนือระดับ 50 ขณะที่ Non-manufacturing PMI อยู่ที่ 50.2 และ Composite PMI อยู่ที่ 50.6 แรงหนุนหลักมาจาก high-tech manufacturing / AI-related exports มากกว่าการฟื้นตัวของ domestic demand</span></p><p><span style=''font-weight:700;''>ปัจจัยสนับสนุน</span></p><ul><li><span>การจัดสรรงบประมาณใหม่ตามนโยบาย AI+ หลังการประชุม Politburo ช่วงปลายเดือนเมษายนที่ผ่านมา อาจเป็นแรงหนุนทางบวกกับ supply chain AI ของจีนในประเทศ</span></li><li><span>กลุ่มที่ได้ประโยชน์สอดคล้องกับนโยบายระยะยาวของจีน ได้แก่ semiconductor localization, industrial automation, AI infrastructure, grid และ high-end equipment โดยมีโอกาสที่รัฐบาลจีนจะใช้นโยบาย Support กลุ่มดังกล่าว</span></li><li><span>Valuation เริ่มสะท้อนปัจจัยพื้นฐานมากขึ้น โดย MSCI China forward P/E ฟื้นตัวจากระดับใกล้ -2SD กลับสู่บริเวณค่าเฉลี่ยที่ประมาณ 10–11 เท่า</span></li></ul><p><span style=''font-weight:700;''>ปัจจัยเสี่ยง</span></p><ul><li><span>ภาคอสังหาริมทรัพย์ยังเป็น overhang สำคัญ โดย investment ภาคอสังหาริมทรัพย์ลดลงแรง และราคาบ้านมือสองใน 100 เมืองลดลง 0.42% MoM ในเดือนมิถุนายน เร็วขึ้นจากเดือนก่อนหน้า</span></li><li><span>ความเสี่ยง deflation / price war ยังมีอยู่ เพราะ factory gate prices และ pricing power ในหลายอุตสาหกรรมยังถูกกดดัน แม้ปริมาณการผลิตในบางกลุ่มจะขยายตัว</span></li></ul><p><span style=''font-weight:700;''>แนวโน้ม/กลยุทธ์:</span> <span>คงคำแนะนำ Neutral สำหรับ Satellite portfolio ในระยะ 12 เดือนข้างหน้า โดย Key สุดท้ายคือการรายงานผลประกอบการ ซึ่ง Yuanta CIO อยากเห็นสัญญาณกำไรผ่านจุดต่ำสุดไปแล้วก่อนปรับเพิ่มน้ำหนัก</span></p><p><img src="https://43844850.fs1.hubspotusercontent-na2.net/hubfs/43844850/monthly-reports/2026-07-01/images/page_48.png" width=''1282'' height=''890'' loading=''lazy'' alt=''MSCI China Forward PE Band Jul 2021–2026'' style=''height: auto; max-width: 100%; width: 1282px; margin-left: auto; margin-right: auto; display: block;''></p><p style=''text-align: center;''><span style=''font-size: 12px; color: #6b7280;''>รูป: MSCI China Forward PE Band Jul 2021–2026</span></p></div></div><p>&nbsp;</p><div style=''border:1px solid #e6e9ee;border-radius:10px;margin-bottom:16px;overflow:hidden;''><div style=''display:flex;justify-content:space-between;align-items:center;gap:10px;padding:12px 16px;background:#f7f8fa;border-bottom:1px solid #e6e9ee;''><span style=''font-size:16px;font-weight:700;color:#16202e;''>หุ้นไทย (TH Equity)</span><span style=''display:inline-block;font-size:12px;font-weight:700;border-radius:6px;padding:2px 9px;background:#eef1f5;border:1px solid #d4dbe4;color:#5b6675;''>Neutral</span></div><div style=''padding:14px 16px;''><p><span>ภาพรวม: ตลาดหุ้นไทยใน 2Q26 ฟื้นตัวเด่น โดย SET Index ปรับขึ้นราว 7% QTD และ SET50 ปรับขึ้นราว 5% QTD หลังความตึงเครียดตะวันออกกลางคลี่คลายเร็วกว่าคาด ราคาน้ำมันอ่อนตัวลง และกระแส AI/Data Center ช่วยหนุน sentiment ของสินทรัพย์เสี่ยง Yuanta ปรับเป้าหมาย SET Index กลางปี 2027 เป็น 1,650 จุด จากเดิม 1,560 จุด อิง EPS ที่ 97 บาท/หุ้น และ PER 17.0 เท่า หรือราว +0.5 S.D. ของค่าเฉลี่ย 10 ปีย้อนหลัง โดยมี Upside จากระดับปัจจุบันราว 6–7% และคาด Dividend Yield เฉลี่ยราว 4% ต่อปี</span></p><p><span style=''font-weight:700;''>ปัจจัยสนับสนุน</span></p><ul><li><span>แรงขับเคลื่อนหลักมาจากการลงทุนภาครัฐและเอกชน การส่งออกที่ยังโตดี และการท่องเที่ยวที่ฟื้นตัวเร็วกว่าคาด ส่งผลบวกต่อธนาคารพาณิชย์, โรงไฟฟ้า, นิคมอุตสาหกรรม, รับเหมาก่อสร้าง, วัสดุก่อสร้าง และสื่อสาร</span></li><li><span>Policy Momentum ใน 3Q26 จากการเร่งเบิกจ่ายงบลงทุนภาครัฐช่วงปลายปีงบประมาณ, โครงการไทยช่วยไทยพลัส, TISA, BOI Fast Track และการลงทุนใน Data Center / Digital Infrastructure</span></li><li><span>หาก พ.ร.ก. เงินกู้ 2 แสนล้านบาทเพื่อการลงทุนด้านพลังงานและโครงสร้างพื้นฐานเดินหน้าต่อ จะหนุนธีม Grid & Power Infrastructure, Clean Power & Utilities, Data Center & Digital Infrastructure และ Battery Ecosystem & EV Charging</span></li><li><span>Best Case ประเมิน SET Index ที่ 1,700 จุด อิง EPS 100 บาท/หุ้น หรือเติบโต 22% YoY และ PER 17.0 เท่า</span></li></ul><p><span style=''font-weight:700;''>ปัจจัยเสี่ยง</span></p><ul><li><span>สถานการณ์ตะวันออกกลางกลับมาปะทุอาจดันราคาน้ำมันและเงินเฟ้อให้กดดันต้นทุน รวมถึงทำให้ sentiment สินทรัพย์เสี่ยงอ่อนตัว</span></li><li><span>ค่าเงินบาทมีความเสี่ยงผันผวนแรงในช่วงใกล้เลือกตั้งกลางเทอมของสหรัฐฯ หากเงินบาทพลิกมาแข็งค่าเร็ว อาจกดดันผลประกอบการของบริษัทส่งออก</span></li><li><span>Worst Case ประเมิน SET Index ที่ 1,560 จุด อิง EPS 95 บาท/หุ้น หรือเติบโต 16% YoY และ PER 16.5 เท่า หาก พ.ร.ก. เงินกู้ไม่ผ่าน อาจทำให้บางโครงการล่าช้าประมาณ 2–3 เดือน</span></li></ul><p><span style=''font-weight:700;''>แนวโน้ม/กลยุทธ์:</span> <span>Yuanta CIO ปรับคำแนะนำเป็น Neutral และ เลือกลงทุนลักษณะทยอยสะสมเมื่ออ่อนตัว มากกว่าการไล่ซื้อทั้งตลาด โดยหุ้นแนะนำ ได้แก่ BBIK, BCH, BEM, CBG, GUNKUL และ SINGER</span></p><p><img src="https://43844850.fs1.hubspotusercontent-na2.net/hubfs/43844850/monthly-reports/2026-07-01/images/page_49_02.png" width=''1282'' height=''890'' loading=''lazy'' alt=''SET Index Mid-2027 Target Forecast Table'' style=''height: auto; max-width: 100%; width: 1282px; margin-left: auto; margin-right: auto; display: block;''></p><p style=''text-align: center;''><span style=''font-size: 12px; color: #6b7280;''>รูป: SET Index Mid-2027 Target Forecast Table</span></p></div></div><p>&nbsp;</p><h3><span>Yuanta Structured Product — Global Fixed Coupon Notes (Global FCN)</span></h3><p><span>นอกเหนือจากการลงทุนในหุ้นโดยตรง Yuanta Wealth ยังนำเสนอ Global Fixed Coupon Notes (Global FCN) ซึ่งเป็นหุ้นกู้ที่มีอนุพันธ์แฝงอ้างอิงหุ้นต่างประเทศ ออกแบบมาเพื่อเพิ่มโอกาสสร้างผลตอบแทนที่สูงกว่าดอกเบี้ยเงินฝากและตราสารหนี้ทั่วไป เหมาะสำหรับผู้ลงทุนรายใหญ่ (High Net Worth) ตามเกณฑ์ของ ก.ล.ต. ที่ต้องการกระแสเงินสดสม่ำเสมอ ต้องการซื้อหุ้นในราคาที่ต่ำกว่าตลาด หรือต้องการสร้างผลตอบแทนที่สูงในช่วงที่ตลาดหุ้นเคลื่อนไหวในกรอบแคบ (Sideways)</span></p><p>&nbsp;</p><div style=''border:1px solid #e6e9ee;border-radius:10px;margin-bottom:16px;overflow:hidden;''><div style=''display:flex;justify-content:space-between;align-items:center;gap:10px;padding:12px 16px;background:#f7f8fa;border-bottom:1px solid #e6e9ee;''><span style=''font-size:16px;font-weight:700;color:#16202e;''>Global FCN — ตะกร้าหุ้น AMAT / AVGO / NVDA</span></div><div style=''padding:14px 16px;''><p><span>ภาพรวม: ผลิตภัณฑ์ Global FCN ล่าสุดที่ Yuanta นำเสนอ ณ วันที่ 2 ก.ค. 2569 อ้างอิงตะกร้าหุ้น 3 ตัว ได้แก่ Applied Materials (AMAT), Broadcom (AVGO) และ NVIDIA (NVDA) ซึ่งสอดคล้องกับ Yuanta CIO Investment Theme ในกลุ่มเซมิคอนดักเตอร์สหรัฐฯ</span></p><p><span style=''font-weight:700;''>รายละเอียดตะกร้าหุ้น (Basket Details)</span></p><div data-hs-responsive-table=''true'' style=''overflow-x: auto; overflow-y: auto; max-height: 520px; max-width: 100%; width: 100%; margin-left: auto; margin-right: auto;''><table style=''width: 100%; border-collapse: collapse; table-layout: fixed; border: 1px solid #99acc2;''><tbody><tr><td style=''padding: 4px; background-color: #a2603c; text-align: center;''><span style=''color: #ffffff;''>รายการ</span></td><td style=''padding: 4px; background-color: #a2603c; text-align: center;''><span style=''color: #ffffff;''>รายละเอียด</span></td></tr><tr><td style=''padding: 4px;''><span>Underlying</span></td><td style=''padding: 4px;''><span>AMAT, AVGO, NVDA</span></td></tr><tr><td style=''padding: 4px;''><span>Coupon (p.a.)</span></td><td style='