insert into "monthly_asset_class_outlook" ("path", "hs_name", "week_slug", "main_title", "page_subtitle", "sub_title", "page_date", "week_start_date", "week_end_date", "cover_image", "description", "ai_summary", "body", "is_published") values ('2026-07-01-fixed-income', 'มุมมองตราสารหนี้เดือนกรกฎาคม 2569: Bear Flattening กดดันต่อเนื่อง เน้น Carry First, Duration Later', '2026-07-01', 'มุมมองตราสารหนี้เดือนกรกฎาคม 2569: Bear Flattening กดดันต่อเนื่อง เน้น Carry First, Duration Later', 'มุมมองการลงทุนรายเดือน — ตราสารหนี้ กรกฎาคม 2569', 'ตราสารหนี้', '2026-07-01', '2026-07-01', '2026-07-31', NULL, NULL, '<p><span>ตลาดตราสารหนี้โลกเผชิญภาวะ Bear Flattening ภายใต้การนำของ Kevin Warsh ขณะที่ตราสารหนี้ไทยถูกกดดันจากเงินเฟ้อและ Bond Supply ที่เพิ่มขึ้น Yuanta CIO แนะนำ Neutral สำหรับ Global Fixed Income และ Slightly Underweight สำหรับตราสารหนี้ไทย พร้อมเน้นกลยุทธ์ Carry First, Duration Later และ Defensive Barbell ในช่วง Short-to-Intermediate Duration</span></p>', '<h3><span>ภาพรวมตราสารหนี้เดือนกรกฎาคม 2569</span></h3>
<p><span>เดือนกรกฎาคม 2569 Yuanta CIO คงน้ำหนัก Neutral สำหรับ Global Fixed Income และ Slightly Underweight สำหรับตราสารหนี้ไทย โดยภาพรวมตลาดตราสารหนี้ทั้งโลกและไทยยังคงเผชิญแรงกดดันจากภาวะ Bear Flattening การส่งสัญญาณขึ้นดอกเบี้ยเพิ่มเติมของเฟด และเงินเฟ้อที่ยังอยู่ในระดับสูง กลยุทธ์หลักที่ Yuanta CIO ย้ำในเดือนนี้คือ "Carry First, Duration Later" ซึ่งเน้นการรับดอกเบี้ยระยะสั้นสูงและหลีกเลี่ยงการเพิ่ม Duration ยาวเชิงรุก</span></p>

<p>&nbsp;</p>

<div style=''border:1px solid #e6e9ee;border-radius:10px;margin-bottom:16px;overflow:hidden;''>
  <div style=''display:flex;justify-content:space-between;align-items:center;gap:10px;padding:12px 16px;background:#f7f8fa;border-bottom:1px solid #e6e9ee;''>
    <span style=''font-size:16px;font-weight:700;color:#16202e;''>ตราสารหนี้โลก (Global Fixed Income)</span>
    <span style=''display:inline-block;font-size:12px;font-weight:700;border-radius:6px;padding:2px 9px;background:#eef1f5;border:1px solid #d4dbe4;color:#5b6675;''>Neutral</span>
  </div>
  <div style=''padding:14px 16px;''>
    <p><span>ภาพรวม: ตราสารหนี้โลกในเดือนพฤษภาคมมีความผันผวนต่อเนื่อง หลัง ECB และ BOJ เดินหน้าปรับขึ้นดอกเบี้ยตามที่ตลาดคาดการณ์ ขณะที่เฟดภายใต้การนำของ Kevin Warsh ได้นำ Alan Greenspan playbook มาใช้อย่างเต็มที่ ทำให้นักลงทุนต้องเผชิญกับภาวะ Bear Flattening ตลอดทั้งเดือนมิถุนายนที่ผ่านมา นอกจากนี้ Dotplot ถูกขยับให้เห็นว่าปีนี้จะมีการปรับขึ้นดอกเบี้ยอีกราว 25 BPS โดย CME ล่าสุดประเมินว่าจะมีการขึ้นดอกเบี้ยในช่วงเดือนกันยายน การสื่อสารที่น้อยลงของ Warsh ยังทำให้ตลาดต้องตีความตัวเลขเศรษฐกิจด้วยตนเองมากกว่าอิงจาก Fed Speech</span></p>

    <p><img src="https://43844850.fs1.hubspotusercontent-na2.net/hubfs/43844850/monthly-reports/2026-07-01/images/page_050.png" width=''1282'' height=''890'' loading=''lazy'' alt=''Next 12M Return During Bear Flattening Regimes'' style=''height: auto; max-width: 100%; width: 1282px; margin-left: auto; margin-right: auto; display: block;''></p>
    <p style=''text-align: center;''><span style=''font-size: 12px; color: #6b7280;''>รูป: Next 12M Return During Bear Flattening Regimes</span></p>

    <p><span>จากกราฟ Next 12M Return During Bear Flattening Regimes พบว่าในภาวะ Bear Flattening ผลตอบแทน 12 เดือนข้างหน้าอยู่ที่เพียง 0.834% ซึ่งต่ำที่สุดในบรรดาทุก Regime เมื่อเทียบกับ Bear Steepening (3.043%), Bull Flattening (5.931%), Bull Steepening (8.545%) และค่าเฉลี่ย (4.588%) สะท้อนให้เห็นว่าสภาพแวดล้อมปัจจุบันเป็นหนึ่งในช่วงที่ยากที่สุดสำหรับการลงทุนในตราสารหนี้</span></p>

    <p><span style=''font-weight:700;''>ปัจจัยสนับสนุน</span></p>
    <ul>
      <li><span>ตลาดสะท้อนความกลัวด้าน Stagflation ไปเป็นส่วนมากแล้ว ซึ่งเห็นได้ชัดจาก Core PCE Projection รอบการประชุมเฟดเดือนมิถุนายน ที่ใช้ Assumption ราคาน้ำมันอยู่ในระดับสูงกว่า Consensus</span></li>
      <li><span>หาก Task force ของ Kevin Warsh ส่งสัญญาณนำ Trimmed Mean PCE มาใช้เป็นหนึ่งในปัจจัยกำหนดการขึ้นดอกเบี้ย จะทำให้ตลาดตราสารหนี้กลับขาทันที เนื่องจากความจำเป็นในการขึ้นดอกเบี้ยในปี 2026 จะหายไปในทันที</span></li>
    </ul>

    <p><span style=''font-weight:700;''>ปัจจัยเสี่ยง</span></p>
    <ul>
      <li><span>ในกรณีที่เลวร้ายที่สุดของ Bear Flattening เฟดอาจพลิกกลับมาขึ้นดอกเบี้ยได้ ซึ่งจะกดดันการลงทุนตราสารหนี้ในที่สุด</span></li>
      <li><span>หากดอกเบี้ยอยู่ในระดับสูงยาวนานและกดดันความสามารถในการชำระหนี้ใน Private Credit อาจทำให้ Credit spread โดยรวมกว้างขึ้นได้ ภายใต้แนวทางการควบคุมสภาพคล่องส่วนเกินของ Kevin Warsh</span></li>
    </ul>

    <p><span style=''font-weight:700;''>แนวโน้ม/กลยุทธ์:</span> <span>Yuanta CIO คงคำแนะนำการลงทุนตราสารหนี้สำหรับ Satellite Portfolio ระยะ 12 เดือนขึ้นไป ด้วยน้ำหนัก Neutral เน้นกลยุทธ์ "Carry First, Duration Later" โดยเน้นดอกเบี้ยรับระยะสั้นระดับสูง พร้อมเลือกช่วงอายุ Short to Intermediate Duration, High Quality Credit และ Carry Income จัด Portfolio ลักษณะ Defensive Barbell ซึ่งเอียงไปทางด้าน Short-end และ Intermediate (3-5 ปี) สำหรับ Core Portfolio แนะนำให้นักลงทุนลงทุนผ่านกองทุน UGISFX-N โดยตั้ง Zone ทยอยลงทุนเมื่อ UST 10Y ปรับตัวขึ้นเหนือ 4.25% และทยอยลงทุนทุกครั้งที่แตะระดับเพิ่มขึ้นครั้งละ 0.25% เพื่อสร้าง Income ระยะยาว</span></p>
  </div>
</div>

<p>&nbsp;</p>

<div style=''border:1px solid #e6e9ee;border-radius:10px;margin-bottom:16px;overflow:hidden;''>
  <div style=''display:flex;justify-content:space-between;align-items:center;gap:10px;padding:12px 16px;background:#f7f8fa;border-bottom:1px solid #e6e9ee;''>
    <span style=''font-size:16px;font-weight:700;color:#16202e;''>ตราสารหนี้ไทย (Thailand Fixed Income)</span>
    <span style=''display:inline-block;font-size:12px;font-weight:700;border-radius:6px;padding:2px 9px;background:#fbecec;border:1px solid #f0c6c6;color:#b3372f;''>Slightly Underweight</span>
  </div>
  <div style=''padding:14px 16px;''>
    <p><span>ภาพรวม: ตราสารหนี้ไทยยังเผชิญแรงกดดันจากเงินเฟ้อที่กลับมากดดันผลตอบแทนที่แท้จริง ขณะที่เศรษฐกิจไทยแม้การส่งออกจะเติบโต แต่ก็ยังถูกปัจจัยด้านราคาพลังงานเข้ามากดดัน พรก. เงินกู้ที่ได้รับการอนุมัติ 4 แสนล้านบาท แม้จะมีการปรับโครงสร้างพื้นฐานพลังงานราว 2 แสนล้านบาท ซึ่งดีต่อเศรษฐกิจไทยในระยะยาว แต่ไม่ได้ตอบโจทย์ปัญหาด้านเงินเฟ้อในระยะสั้น ทำให้ "ผลตอบแทนคาดหวัง" ของการลงทุนในตราสารหนี้ไทยนั้นควรสูงกว่าระดับปัจจุบันที่ 2.02%</span></p>

    <p><img src="https://43844850.fs1.hubspotusercontent-na2.net/hubfs/43844850/monthly-reports/2026-07-01/images/page_051.png" width=''1282'' height=''890'' loading=''lazy'' alt=''Thailand Inflation and TH-US Real Yield Spread'' style=''height: auto; max-width: 100%; width: 1282px; margin-left: auto; margin-right: auto; display: block;''></p>
    <p style=''text-align: center;''><span style=''font-size: 12px; color: #6b7280;''>รูป: Thailand Inflation and TH-US Real Yield Spread</span></p>

    <p><span>จากกราฟ Thailand Inflation and TH-US Real Yield Spread สะท้อนว่า Real Yield Spread ของไทยเทียบสหรัฐฯ ปัจจุบันอยู่ในเขตที่ "Expensive" กว่าสหรัฐฯ โดยเปรียบเทียบ โดยพบว่าเงินเฟ้อเป็นส่วนสำคัญที่ทำให้ผลตอบแทนคาดหวังของการลงทุนตราสารหนี้ในไทยควรสูงกว่าในปัจจุบันมากกว่านี้</span></p>

    <p><span style=''font-weight:700;''>ปัจจัยสนับสนุน</span></p>
    <ul>
      <li><span>หากรัฐบาลไม่ได้ใช้วงเงินกู้เต็มจำนวนทันที หรือทยอยออกพันธบัตรแบบไม่กระจุกตัว แรงกดดันจาก Bond Supply อาจต่ำกว่าที่ตลาดกังวล และทำให้ TH 10Y Yield ปรับขึ้นจำกัด</span></li>
      <li><span>หากพรก. เงินกู้ส่วนที่เหลือราว 2 แสนล้านบาทนำมาใช้ลดหย่อนค่าครองชีพในลักษณะเดียวกับที่ญี่ปุ่นทำในช่วงเดือนเมษายน – พฤษภาคมที่ผ่านมา จะช่วยลดเงินเฟ้อได้และทำให้ระดับผลตอบแทนของ TH 10Y กลับมาอยู่ในระดับที่น่าสนใจอีกครั้ง</span></li>
    </ul>

    <p><span style=''font-weight:700;''>ปัจจัยเสี่ยง</span></p>
    <ul>
      <li><span>การพลิกกลับมาขึ้นดอกเบี้ยของ BOT หาก Policy Spread กับธนาคารกลางอื่นมีแนวโน้มกว้างขึ้น ซึ่งหากเงินเฟ้อยังยืนสูงนานและ GDP Growth ยังฟื้นได้จาก Export อาจเห็น BOT มีโอกาสขยาย Policy Space</span></li>
      <li><span>Real Yield Spread ไทยเทียบสหรัฐฯ ปัจจุบันอยู่ในเขตที่ "Expensive" กว่าสหรัฐฯ โดยเปรียบเทียบ ทำให้ Valuation ยังอยู่ในระดับ "Expensive"</span></li>
      <li><span>แรงกดดันจากการขาดดุลและการออกพันธบัตรเพิ่มเติมยังเป็นปัจจัยกดดันต่อเนื่อง</span></li>
    </ul>

    <p><span style=''font-weight:700;''>แนวโน้ม/กลยุทธ์:</span> <span>Yuanta CIO คงมุมมอง Slightly Underweight ต่อ Thailand Fixed Income เพราะแม้นโยบายรัฐบาลจะหนุนตลาดหุ้น แต่ไม่ได้เป็นมิตรกับตลาดตราสารหนี้ กลยุทธ์ยังควรเน้นตราสารหนี้ไทยช่วงอายุสั้นถึงกลางมากกว่าการเพิ่ม Duration ยาวเชิงรุก โดยประเมินว่าความน่าสนใจจะกลับมาก็ต่อเมื่อตลาดตราสารหนี้โลกเริ่มสะท้อนภาพการลดดอกเบี้ยของสหรัฐฯ มากขึ้น สำหรับด้านการลดดอกเบี้ยในช่วงต่อจากนี้ ประเมินว่า BOT อาจทำได้ค่อนข้างยากจาก Policy Space ที่จำกัดและเงินเฟ้อที่อยู่ในระดับสูง</span></p>
  </div>
</div>', true);
insert into "monthly_asset_class_outlook" ("path", "hs_name", "week_slug", "main_title", "page_subtitle", "sub_title", "page_date", "week_start_date", "week_end_date", "cover_image", "description", "ai_summary", "body", "is_published") values ('2026-07-01-global-fixed-income-portfolio', 'พอร์ตตราสารหนี้โลก กรกฎาคม 2569: Defensive Barbell รับดอกเบี้ยลดช้า เน้น Carry Yield 4.01%', '2026-07-01', 'พอร์ตตราสารหนี้โลก กรกฎาคม 2569: Defensive Barbell รับดอกเบี้ยลดช้า เน้น Carry Yield 4.01%', 'มุมมองการลงทุนรายเดือน — พอร์ตตราสารหนี้โลก กรกฎาคม 2569', 'พอร์ตตราสารหนี้โลก', '2026-07-01', '2026-07-01', '2026-07-31', NULL, NULL, '<p><span>พอร์ตตราสารหนี้โลกเดือนกรกฎาคม 2569 จัดสรรเป็นกลยุทธ์ Defensive Barbell ผสมหุ้นกู้ Investment Grade ระยะสั้นและระยะกลาง อายุเฉลี่ย 1.89 ปี ให้ YTM 4.01% สูงกว่าพันธบัตรสหรัฐฯ 2 ปี</span></p><p><span>ผู้ออกตราสารครอบคลุมหลายอุตสาหกรรม ได้แก่ JPMorgan, Apple, Walmart, 7-Eleven, Hyundai Capital และ Broadcom ทั้งหมดอยู่ในระดับ Investment Grade</span></p>', '<h3><span>ภาพรวมพอร์ตตราสารหนี้โลก</span></h3>
<p><span>ในเดือนกรกฎาคม 2569 Yuanta แนะนำจัดพอร์ตตราสารหนี้โลกด้วยกลยุทธ์ Defensive Barbell โดยเน้นหุ้นกู้เอกชนคุณภาพสูงระดับ Investment Grade ทั้งในส่วน Short Duration และ Intermediate Duration เพื่อรองรับสภาวะ Bear Flattening ที่อัตราดอกเบี้ยมีแนวโน้มลดลงช้า พอร์ตโดยรวมมีอายุตราสารเฉลี่ย 1.89 ปี และให้ผลตอบแทน (YTM) ที่ 4.01% ซึ่งสูงกว่าพันธบัตรรัฐบาลสหรัฐฯ อายุ 2 ปี โดยผู้ออกตราสารกระจายอยู่ในหลายอุตสาหกรรม ได้แก่ ธนาคาร เทคโนโลยี ค้าปลีก ร้านสะดวกซื้อ สินเชื่อยานยนต์ และเซมิคอนดักเตอร์</span></p>
<p>&nbsp;</p><h3><span>หลักการจัดพอร์ต: 4 เสาหลัก</span></h3>
<div style=''border:1px solid #e6e9ee;border-radius:10px;margin-bottom:16px;overflow:hidden;''>
  <div style=''display:flex;justify-content:space-between;align-items:center;gap:10px;padding:12px 16px;background:#f7f8fa;border-bottom:1px solid #e6e9ee;''>
    <span style=''font-size:16px;font-weight:700;color:#16202e;''>กลยุทธ์ภาพรวม: Defensive Barbell</span>
  </div>
  <div style=''padding:14px 16px;''>
    <p><span>ภาพรวม: พอร์ตนี้ถูกออกแบบมาเพื่อสภาวะที่อัตราดอกเบี้ยลดลงช้า (Bear Flattening) โดยยึดหลัก 4 ประการ ดังนี้</span></p>
    <ul>
      <li><span>Defensive Barbell: จัดพอร์ตเน้น Duration สั้นผสมระยะกลางรับดอกเบี้ยลดช้า</span></li>
      <li><span>Carry First: พอร์ตนี้เน้น Yield ให้สูงและเน้นลงทุนในบริษัทคุณภาพดีสามารถชำระหนี้สินได้ในระยะยาว</span></li>
      <li><span>Duration Later: อายุตราสารหนี้เฉลี่ยของพอร์ตโดยรวมคือ 1.89 ปี และให้ผลตอบแทนที่สูงกว่าพันธบัตรสหรัฐฯ ที่อายุ 2 ปี</span></li>
      <li><span>High Flexibility: กรณีดอกเบี้ยลดช้านักลงทุนได้รับ Carry yield ที่ 4.01% หากดอกเบี้ยลดเร็วนักลงทุนยังลุ้น Capital gain ได้ด้วยเช่นกัน</span></li>
    </ul>
  </div>
</div>
<p>&nbsp;</p><h3><span>รายละเอียดตราสารทั้งหมดในพอร์ต</span></h3>
<p><span>ตารางด้านล่างแสดงตราสารทุกรายการในพอร์ต Defensive Barbell ณ วันที่ 2 กรกฎาคม 2569 (หน่วย: USD)</span></p>
