insert into "monthly_asset_class_outlook" ("path", "hs_name", "week_slug", "main_title", "page_subtitle", "sub_title", "page_date", "week_start_date", "week_end_date", "cover_image", "description", "ai_summary", "body", "is_published") values ('2026-07-01-gold', 'มุมมองทองคำเดือนกรกฎาคม 2569: Downside เริ่มจำกัด แต่ Upside ยังไม่เปิด', '2026-07-01', 'มุมมองทองคำเดือนกรกฎาคม 2569: Downside เริ่มจำกัด แต่ Upside ยังไม่เปิด', 'มุมมองการลงทุนรายเดือน — ทองคำ กรกฎาคม 2569', 'Gold', '2026-07-01', '2026-07-01', '2026-07-31', NULL, NULL, '<p><span>Yuanta CIO คงมุมมอง Neutral สำหรับทองคำ โดยประเมินราคาเป้าหมาย 12 เดือนที่ 4,399 ดอลลาร์/ออนซ์ และ 24 เดือนที่ 4,532 ดอลลาร์/ออนซ์ โดย Downside เริ่มจำกัดลงเมื่อ DXY อยู่ในกรอบ 100–110 แต่ยังแนะนำเพียง "ถือ" ในสัดส่วนไม่เกิน 5% ของพอร์ตเพื่อการกระจายความเสี่ยง ผ่าน DR อย่าง GOLD19</span></p>', '<h3><span>ภาพรวมทองคำประจำเดือนกรกฎาคม 2569</span></h3>
<p><span>Yuanta CIO คงมุมมองทองคำที่ <span style=''display:inline-block;font-size:12px;font-weight:700;border-radius:6px;padding:2px 9px;background:#eef1f5;border:1px solid #d4dbe4;color:#5b6675;''>Neutral</span> โดยแบบจำลองทางเศรษฐมิติที่ผสมผสาน VECM (5%), VAR (50%) และ ARMAX (45%) ประเมินราคาเป้าหมายทองคำในอีก 12 เดือนข้างหน้าไว้ที่ 4,399 ดอลลาร์/ออนซ์ และ 24 เดือนข้างหน้าที่ 4,532 ดอลลาร์/ออนซ์ แบบจำลองมีความสามารถในการอธิบายเฉลี่ยที่ 67% โดยมีตัวแปรหลักได้แก่ อัตราผลตอบแทนพันธบัตรรัฐบาลสหรัฐฯ 2 ปีและ 10 ปี, ราคาน้ำมัน, geopolitical risk, Momentum, US CPI, US equity, recession probability และ Dollar Index แม้ว่าแบบจำลองจะสะท้อนว่าราคาทองคำยังมี upside ในเชิงโมเดล แต่ยังไม่มากพอที่จะเพิ่มน้ำหนักเชิงรุก</span></p>

<p>&nbsp;</p>

<div style=''border:1px solid #e6e9ee;border-radius:10px;margin-bottom:16px;overflow:hidden;''>
  <div style=''display:flex;justify-content:space-between;align-items:center;gap:10px;padding:12px 16px;background:#f7f8fa;border-bottom:1px solid #e6e9ee;''>
    <span style=''font-size:16px;font-weight:700;color:#16202e;''>ทองคำ (Gold)</span>
    <span style=''display:inline-block;font-size:12px;font-weight:700;border-radius:6px;padding:2px 9px;background:#eef1f5;border:1px solid #d4dbe4;color:#5b6675;''>Neutral</span>
  </div>
  <div style=''padding:14px 16px;''>

    <p><span style=''font-weight:700;''>ภาพรวม (Overview)</span></p>
    <p><span>Yuanta CIO คงจุดยืน Neutral สำหรับทองคำในเดือนกรกฎาคม 2569 โดยแบบจำลองประเมินราคาเป้าหมายกรณีฐาน (Base Case) ในอีก 12 เดือนที่ 4,399 ดอลลาร์/ออนซ์ (upside 7.07%) และ 24 เดือนที่ 4,532 ดอลลาร์/ออนซ์ (upside 9.80%) ปัจจัยหลักที่กดดันราคาทองคำขณะนี้คือ Dollar Index และท่าทีของ Fed ที่ยัง hawkish โดยเฉพาะในช่วงที่ตลาดประเมินว่า Fed อาจไม่สามารถลดดอกเบี้ยได้ตามที่คาดไว้ อย่างไรก็ตาม Downside ของทองคำเริ่มจำกัดมากขึ้น โดยเฉพาะเมื่อ Dollar Index อยู่ในกรอบ 100–110 ซึ่งข้อมูลในอดีตชี้ว่าผลตอบแทนเฉลี่ยในอีก 12 เดือนข้างหน้าอยู่ที่ 14.58% และผลขาดทุนสูงสุดเฉลี่ยอยู่ที่ -8.59% ให้ค่า Return/Maximum Drawdown ที่ 1.697 เท่า ซึ่งดีกว่ากรอบ DXY อื่น ๆ อย่างมีนัยสำคัญ</span></p>

    <p>&nbsp;</p>

    <p><span style=''font-weight:700;''>ราคาเป้าหมาย (Target Price)</span></p>
